        r = await koop(g, **{who: kat(74, 14), other: kat(72, 14)}, plans={who: takt(9, list(range(79, 104, 3)), kx(108), 77, 2) + [k_lauf(110)]}, maxFrames=4000)
        soll(r.get('done'), f'Takt-Steine 2 s ({who})', r.get('pos'))
