    f = [k_lauf(315), {'hold': ['right'], 'until': f'P.y < {ky(5)}', 'frames': 100}, {'frames': 1, 'hold': ['right']}, {'hold': ['right', 'glide'], 'until': 'P.grounded', 'frames': 600}]
