    soll(k_pos(r, 'm') and k_pos(r, 'm')[1] == 5 and await g.ev("!!linkOn[1]"), 'Affe auf den Felsen + Hebel 1', r.get('pos'))
    def welle(w):
        pl = [{'frames': w + 1}]
        for c in range(100, 141, 5):
            fi = f'fallen.find(f => f.x === {c*40} && f.y === {12*40})'
