        soll(ok, 'E4 Schleuder A: Affe über Grube A (Hebel 8 an)', ok)
        ok = []
        for rel in RELS:
            r = await koop(g, m=kat(688, 15), f=kat(690, 15), plans={'m': kette(691, 3, rel) + am(720)}, maxFrames=4000)
