        pkette = lambda w: [{'aim': [kx(132), kx(139), kx(146), kx(153), kx(159)], 'jumps': [kx(125)], 'glide': w == 'f', 'until': f'P.grounded && P.x > {kx(156)}', 'frames': 900}, durch(168), k_lauf(171)]
