@test
async def asmr_klangbibliothek(g):
    """Alle Geräusche: Klangbibliothek (Stereo, mehrere Varianten) wird gebaut; Abspielen klappt nach dem ersten Tastendruck."""
    st = await g.ev("""(()=>{ const out={}; const it=sfxBuild(new OfflineAudioContext(2,44100,44100), out); while(!it.next().done){}
      const names = Object.keys(out.bank); const bad = names.filter(k => !out.bank[k].length || out.bank[k][0].numberOfChannels !== 2);
      return {names, bad, steps: out.bank.step.length, ir: !!out.ir, vol: names.filter(k => !(k in SFX_VOL))}; })()""")
    need = ['step', 'land', 'jump', 'wall', 'coin', 'hookAttach', 'rope', 'umbrella', 'lever', 'doorOpen', 'doorClose',
            'crumbleWarn', 'crumbleBreak', 'death', 'checkpoint', 'mushroom', 'frog', 'discover', 'bud', 'heart', 'birdFlap', 'menuTick', 'menuOk', 'menuStart']
    assert all(n in st['names'] for n in need) and not st['bad'] and st['steps'] >= 4 and st['ir'] and not st['vol'], f'Bibliothek: {st}'
    await g.p.keyboard.press('KeyF'); await g.p.keyboard.press('KeyF'); await g.p.wait_for_timeout(1500)
    if await g.ev("audioCtx && audioCtx.state === 'running'"):
        try: await g.p.wait_for_function("!!sfxBank", timeout=10000)   # Klangbibliothek wird im Hintergrund gebaut
        except Exception: pass
        assert await g.ev("!!sfxBank && sfxPlay('coin', {x: p1.x})"), 'Geräusch lässt sich nicht abspielen'

@test
async def menue_ton_dezent(g):
    """Design-Politur G: Menü-Klänge sind kurz und tief statt klingelnd – menuTick (Cursor/Zurück) ≤ 50 ms, menuOk
    (Bestätigen) ≤ 80 ms, menuStart (Level-Start) ≤ 120 ms, ohne hohe Spieluhr-Anteile (Energie über 2 kHz klein),
    am Ende verklungen; schnelle Cursor-Schritte klappern nicht (höchstens einer je MENU_TICK_ABSTAND ms)."""
    st = await g.ev("""(()=>{ const out={}; const it=sfxBuild(new OfflineAudioContext(2,44100,44100), out); while(!it.next().done){}
      const r = {};
      for(const n of ['menuTick', 'menuOk', 'menuStart']){
        const buf = out.bank[n][0], d = buf.getChannelData(0), N = d.length;
        let e = 0, hi = 0, tail = 0, prev = 0;
        for(let i = 0; i < N; i++){ e += d[i]*d[i]; const h = d[i] - prev; hi += h*h; prev = d[i]; if(i > N*0.8) tail += d[i]*d[i]; }
        r[n] = {ms: Math.round(buf.duration*1000), hoch: +(hi/(e || 1)).toFixed(3), ende: +(tail/(e || 1)).toFixed(4)};
      }
      return r; })()""")
    grenze = {'menuTick': 50, 'menuOk': 80, 'menuStart': 120}
    for n, v in st.items():
        assert v['ms'] <= grenze[n], f'{n} zu lang: {v}'
        assert v['hoch'] < 0.15, f'{n} zu hell/klingelnd (Anteil hoher Frequenzen): {v}'
        assert v['ende'] < 0.05, f'{n} klingt am Ende noch nach: {v}'
    # schnelle Cursor-Schritte: nur ein Tap je MENU_TICK_ABSTAND
    n = await g.ev("""(()=>{ let c = 0; const alt = SFX.menuTick; SFX.menuTick = () => c++;
      for(let i = 0; i < 5; i++) GameMenu.snd.play('move'); SFX.menuTick = alt; return c; })()""")
    assert n == 1, f'5 schnelle Cursor-Schritte -> {n} Klänge'

@test
async def levelkarten_gleich_breit(g):
    """Design-Politur F: auf der Welt-Seite sind alle Levelkarten (mit und ohne Statistik-Zeile) gleich breit und gleich
    hoch, liegen ganz im Bild und kein Titel ragt aus seiner Karte – bei 1920×1080 und 1366×768, mit 6, 5 und 4 Leveln in
    der Welt (Ruinen) und mit den 2 Abschnitten im Dschungel (Dschungel-Neu, keine Boss-Karte mehr). Lange Titel werden
    kleiner bzw. an einer Silbe umgebrochen."""
    srv = webserver(); p = g.p
    await alle_welten(p)   # Weltkarte/weitere Welten: im Spiel ausgeblendet, hier mit allen Welten
    try:
        await p.goto(srv.url + 'index.html'); await p.wait_for_function("GameMenu.levelsReady()", timeout=8000)
        await g.ev("""localStorage.setItem('monchichi.save', JSON.stringify({v: 2, played: true, unlocked: ['%s', '%s', 'ruinen/01-ruinen.json'],
            completed: ['%s', '%s', 'ruinen/01-ruinen.json'], stats: {'%s': {m: 2, f: 3}, 'ruinen/01-ruinen.json': {m: 1, f: 1}}, bosse: []})); localStorage.setItem('monchichi.introGesehen', 'true')""" % (A1, A2, A1, A2, A1))
        await p.reload(); await p.wait_for_function("GameMenu.levelsReady()", timeout=8000)
        alle = await g.ev("GameMenu.config.levels.map((l, i) => i).filter(i => GameMenu.config.levels[i].welt === 'ruinen')")
        assert len(alle) >= 6, alle
        for w, h in ((1920, 1080), (1366, 768)):
            await p.set_viewport_size({'width': w, 'height': h}); await p.wait_for_timeout(200)
            for n in (6, 5, 4):
                await g.ev(f"{alle}.forEach((i, k) => GameMenu.config.levels[i].welt = k < {n} ? 'ruinen' : '_weg')")
                for welt in ('dschungel', 'ruinen'):
                    await g.ev(f"GameMenu.show('levels', {{world: '{welt}'}})"); await p.wait_for_timeout(450)
                    k = await g.ev("""[...document.querySelectorAll('#sm-cards .lc')].map(b => { const r = b.getBoundingClientRect(), nm = b.querySelector('.nm');
                        return {w: r.width, h: r.height, l: r.left, r: r.right, boss: b.classList.contains('boss'), duel: !!b.querySelector('.duel'),
                                t: nm.textContent, rausW: nm.scrollWidth - nm.clientWidth, rausH: nm.scrollHeight - nm.clientHeight, nmR: nm.getBoundingClientRect().right}; })""")
                    wo = f'{w}x{h}, {welt}, {n} Level'
                    if welt == 'dschungel': assert len(k) == 2 and not any(c['boss'] for c in k) and k[0]['duel'], f'{wo}: {k}'   # ohneBoss
                    else: assert len(k) == n + 1 and k[-1]['boss'] and k[0]['duel'], f'{wo}: {k}'   # Boss-Karte „bald“
                    assert max(c['w'] for c in k) - min(c['w'] for c in k) < 1, f'{wo}: Breiten {[round(c["w"], 1) for c in k]}'
                    assert max(c['h'] for c in k) - min(c['h'] for c in k) < 1, f'{wo}: Höhen {[round(c["h"], 1) for c in k]}'
                    assert min(c['l'] for c in k) >= 0 and max(c['r'] for c in k) <= w, f'{wo}: Karten ragen aus dem Bild'
                    for c in k:
                        assert c['rausW'] <= 1 and c['rausH'] <= 2 and c['nmR'] <= c['r'], f'{wo}: Titel ragt heraus: {c}'
            await g.ev(f"{alle}.forEach(i => GameMenu.config.levels[i].welt = 'ruinen')")
    finally:
        await p.set_viewport_size({'width': 1280, 'height': 720})
        await g.ev("localStorage.clear()")
        srv.shutdown()

# Design-Politur A: Obergrenze für die Zeichenzeit eines Bildes (ms) bei doppelter Pixeldichte – großzügig über den
# Messwerten (2–4 ms im Testbrowser), fängt aber Ausreißer wie die frühere Dunkel-Schicht (80–90 ms) sicher ab
ZEICHNEN_MS_GRENZE = 20
LEISTUNG_STELLEN = [('dschungel', 'dschungel/03-lianenschlucht.json', 360), ('ruinen', 'ruinen/04-sonnentempel.json', 292),
                    ('hoehle', 'hoehle/02-tropfsteingang.json', 300), ('vulkan', 'vulkan/01-glutpfad.json', 340)]

# Design-Politur B: Mindest-Kontrast (WCAG-Kontrastverhältnis, Median) zwischen Bodenoberkante und dem Hintergrund
# 16 px darüber, je Welt und Tageszeit (gemessen nach der Politur, mit etwas Abstand gegen Zufall von Tieren/Teilchen)
KONTRAST_MIN = {'mittag': 1.12, 'abend': 1.12, 'nacht': 1.4}   # Mittag: Ruinen am schwächsten (~1,26); Abend: warmes Orange hinter orangem Boden (~1,17) – die dunkle Kontur trennt dort
KONTRAST_MIN_WELT = {'hoehle': 1.35, 'vulkan': 1.55}   # eigene Untergrenze für dunkle Welten (gilt zu jeder Tageszeit)
KONTRAST_JS = r"""() => {
  const L = (r, g, b) => { const f = v => { v /= 255; return v <= 0.03928 ? v/12.92 : Math.pow((v+0.055)/1.055, 2.4); }; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b); };
  const img = ctx.getImageData(0, 0, cvs.width, cvs.height).data, Wc = cvs.width, Hc = cvs.height;
  const lumAt = (sx, sy, r) => { let s = 0, n = 0; for(let dy = -r; dy <= r; dy++) for(let dx = -r; dx <= r; dx++){ const x = Math.round(sx)+dx, y = Math.round(sy)+dy;
    if(x < 0 || y < 0 || x >= Wc || y >= Hc) continue; const i = (y*Wc+x)*4; s += L(img[i], img[i+1], img[i+2]); n++; } return n ? s/n : null; };
  const scr = (wx, wy) => [((wx - camX)*zoom)*RS, (wy*zoom + H*(1-zoom) + CEILING_MARGIN)*RS];
  const cr = (a, b) => (Math.max(a, b) + 0.05)/(Math.min(a, b) + 0.05), out = [];
  const sichtbar = (x, y) => x > 8 && y > 8 && x < Wc - 8 && y < Hc - 8;
  for(const so of solids){
    if(so.type === 'oneway' || so.gone || so.w < 40) continue;
    for(let px = so.x + 20; px < so.x + so.w - 10; px += 80){
      const [ix, iy] = scr(px, so.y + 5), [ox, oy] = scr(px, so.y - 16);
      if(!sichtbar(ix, iy) || !sichtbar(ox, oy)) continue;
      if(solids.some(o => o !== so && px >= o.x && px < o.x + o.w && so.y - 16 >= o.y && so.y - 16 < o.y + o.h)) continue;
      const a = lumAt(ix, iy, 2*RS), b = lumAt(ox, oy, 2*RS); if(a != null && b != null) out.push(cr(a, b));
    }
  }
  return out; }"""

@test
async def kontur_wand_boden_einheitlich(g):
    """Nutzerwunsch: Wand und Boden haben immer dieselbe Outline – gleiche Breite an allen freien Seiten (oben, unten,
    links, rechts). Neues Aussehen (Runde 1): Outline „Weich“ = dünne Innenlinie (outlineDraw, 3,5 px Strich, nur innen
    sichtbar) NUR um die Gesamtform; wo Boden an Wand grenzt (daneben, darauf, darunter) ist es eine Fläche ohne Linie.
    Gemessen mit deckender Prüf-Farbe."""
    G = ground
    srv = webserver(); kx = await g.p.context.browser.new_context(viewport={'width': 1280, 'height': 720}); p = await kx.new_page(); g = Game(p)
    try:
        await p.goto(srv.url + 'index.html'); await p.wait_for_function("GameMenu.levelsReady()", timeout=8000); await p.wait_for_timeout(500)
        await startmenue_bis_level(g)
        await kontur_messen(g, G)
    finally:
        await kx.close(); srv.shutdown()

async def kontur_messen(g, G):
    await g.load(level([G(0, 680, 1600), G(80, 400, 160, 120), G(360, 400, 160, 120, 'wall'),
                        G(640, 400, 80, 120), G(720, 400, 80, 120, 'wall'),          # Boden neben Wand
                        G(900, 320, 120, 80, 'wall'), G(900, 400, 120, 80),           # Wand auf Boden
                        G(1100, 320, 120, 80), G(1100, 400, 120, 80, 'wall')],        # Boden auf Wand
                       {'x': 60, 'y': 680}, {'x': 30, 'y': 680}, welt='dschungel'))
    await g.steps(5); await g.ev("menuScreen = 'pause'")
    r = await g.ev("""(() => { const alt = outlineDraw;
      outlineDraw = (q, edge, clipP) => { q.save(); q.lineJoin = 'round'; q.lineCap = 'round'; q.clip(clipP); q.strokeStyle = '#ff00ff'; q.lineWidth = 3.5; q.stroke(edge); q.restore(); };
      camPos = camX = 0; draw(); outlineDraw = alt;
      const img = ctx.getImageData(0, 0, cvs.width, cvs.height).data, Wc = cvs.width;
      const scr = (wx, wy) => [Math.round(((wx - camX)*zoom)*RS), Math.round((wy*zoom + H*(1-zoom) + CEILING_MARGIN)*RS)];
      const mag = (x, y) => { const i = (y*Wc + x)*4; return img[i] > 170 && img[i+1] < 90 && img[i+2] > 140; };   // Prüf-Farbe (auch unter leichtem Dunst)
      // Prüf-Farbe auf einer Linie durch den Rand zählen (±12 Welt-px um die Kante)
      const quer = (wx, wy, dx, dy) => { const [a0, b0] = scr(wx - dx*12, wy - dy*12), [a1, b1] = scr(wx + dx*12, wy + dy*12);
        let n = 0; const st = Math.max(Math.abs(a1 - a0), Math.abs(b1 - b0));
        for(let k = 0; k <= st; k++){ if(mag(Math.round(a0 + (a1 - a0)*k/st), Math.round(b0 + (b1 - b0)*k/st))) n++; } return n; };
      // je Seite drei Stellen, die breiteste zählt (Tiere/Blätter davor sollen das Messen nicht stören)
      const drei = f => Math.max(f(0.3), f(0.5), f(0.7));
      const seiten = (x, y, w, h) => ({oben: drei(t => quer(x + w*t, y, 0, 1)), unten: drei(t => quer(x + w*t, y + h, 0, 1)),
        links: drei(t => quer(x, y + h*t, 1, 0)), rechts: drei(t => quer(x + w, y + h*t, 1, 0))});
      return {boden: seiten(80, 400, 160, 120), wand: seiten(360, 400, 160, 120), rs: RS, zoom,
        nebeneinander: drei(t => quer(720, 400 + 120*t, 1, 0)), wandAufBoden: drei(t => quer(900 + 120*t, 400, 0, 1)),
        bodenAufWand: drei(t => quer(1100 + 120*t, 400, 0, 1))}; })()""")
    soll = 1.75 * r['zoom'] * r['rs']   # outlineDraw: 3,5 px Strich, nur die innere Hälfte sichtbar
    werte = {**{f'boden_{k}': v for k, v in r['boden'].items()}, **{f'wand_{k}': v for k, v in r['wand'].items()}}
    falsch = {k: v for k, v in werte.items() if abs(v - soll) > 1.6}
    assert not falsch, f'Outline nicht einheitlich (soll ≈ {soll:.1f} Bild-px): {falsch}; alle: {werte}'
    innen = {k: r[k] for k in ('nebeneinander', 'wandAufBoden', 'bodenAufWand') if r[k] > 0}
    assert not innen, f'Linie zwischen Boden und Wand (soll eine Fläche sein): {innen}'
    assert max(werte.values()) - min(werte.values()) <= 2, f'Outline-Breiten unterschiedlich: {werte}'

@test
async def kontrast_mindestwerte(g):
    """Design-Politur B: in jeder Welt (Dschungel, Ruinen, Höhle, Vulkan) zu Mittag, Abend und Nacht hebt sich die
    Bodenoberkante deutlich vom Hintergrund ab – Median des Kontrastverhältnisses mindestens KONTRAST_MIN (Tageszeit)
    bzw. KONTRAST_MIN_WELT; die Tageszeiten bleiben unterscheidbar (mittlere Helligkeit Mittag > Abend > Nacht)."""
    srv = webserver(); kx = await g.p.context.browser.new_context(viewport={'width': 1280, 'height': 720}); p = await kx.new_page(); g = Game(p)
    try:
        await p.goto(srv.url + 'index.html'); await p.wait_for_function("GameMenu.levelsReady()", timeout=8000); await p.wait_for_timeout(800)
        await startmenue_bis_level(g)
        zu_wenig, werte = {}, {}
        for welt, datei, spalte in LEISTUNG_STELLEN:
            await koop_level(g, datei)
            hell = {}
            for zeit in ('mittag', 'abend', 'nacht'):
                pool = []; hs = []
                for sp in (spalte, spalte + 200):
                    await g.ev(f"""(() => {{ menuScreen = null; deathState = null; p1.x = {sp}*40 + 60; p2.x = {sp}*40 + 20; p1.y = p2.y = 100;
                        camPos = camX = Math.max(0, {sp}*40 - 200); setTheme(composeLook('{welt}', '{zeit}')); weatherForce('sun'); }})()""")
                    await g.steps(25); await g.ev(f"menuScreen = 'pause'; camPos = Math.max(0, {sp}*40 - 200)"); await g.ev("draw()")
                    pool += await p.evaluate(KONTRAST_JS)
                    hs.append(await g.ev("(() => { const d = ctx.getImageData(0, 0, cvs.width, cvs.height).data; let s = 0; for(let i = 0; i < d.length; i += 400) s += d[i] + d[i+1] + d[i+2]; return s/(d.length/400)/765; })()"))
                    await g.ev("menuScreen = null")
                med = sorted(pool)[len(pool)//2] if pool else 0
                grenze = KONTRAST_MIN_WELT.get(welt, KONTRAST_MIN[zeit])
                werte[f'{welt}-{zeit}'] = round(med, 2); hell[zeit] = sum(hs)/len(hs)
                if len(pool) < 5 or med < grenze: zu_wenig[f'{welt}-{zeit}'] = (round(med, 2), grenze, len(pool))
            if welt == 'ruinen':
                assert hell['mittag'] > hell['abend'] > hell['nacht'], f'{welt}: Tageszeiten nicht unterscheidbar {hell}'
            if welt == 'dschungel':   # Dschungel-Paket: Abend hat (noch) den neuen Tag-Hintergrund -> nur die Nacht muss dunkler sein
                assert min(hell['mittag'], hell['abend']) > hell['nacht'], f'{welt}: Nacht nicht dunkler {hell}'
        print('    Kontrast:', werte)
        assert not zu_wenig, f'Kontrast zu gering (Wert, Grenze, Messpunkte): {zu_wenig}'
    finally:
        await kx.close(); srv.shutdown()

@test
async def dschungel_look_auswahl(g):
    """Dschungel-Paket: der neue Hintergrund-Stil gilt nur in der Dschungel-Welt (HG_STIL_TABELLE): Tag (mittag) und Nacht
    ganz neu, Morgen/Abend nur der neue Hintergrund (sonst wie bisher); alle anderen Welten und das alte Thema „nacht“
    (Mondnacht, Ruinen-Welt) bleiben wie bisher (kein Stil, alte Ebenen)."""
    r = await g.ev("""(() => { const f = n => { const s = hgStilFuer(n); return s ? s.name : null; };
      return {tag: f('dschungel@mittag'), nacht: f('dschungel@nacht'), morgen: f('dschungel'), abend: f('dschungel@abend'), altAbend: f('abend'),
              altNacht: f('nacht'), andere: ['ruinen', 'ruinen@nacht', 'ruinen@mittag', 'hoehle', 'hoehle@nacht', 'vulkan@abend', 'wasser', 'wasser@nacht'].map(f).filter(x => x)}; })()""")
    assert r == {'tag': 'dschungelTag', 'nacht': 'dschungelNacht', 'morgen': 'dschungelHG', 'abend': 'dschungelHG', 'altAbend': 'dschungelHG',
                 'altNacht': None, 'andere': []}, f'Auswahl falsch: {r}'
    await g.load(level([ground(0, 680, 3000)], {'x': 100, 'y': 680}, {'x': 60, 'y': 680}, welt='ruinen', tageszeit='nacht'))
    r = await g.ev("({stil: BG_STIL, ebenen: BG_LAYERS.length, licht: hgEigenesLicht(), tiere: hgTierRegeln()})")
    assert r == {'stil': None, 'ebenen': 5, 'licht': False, 'tiere': False}, f'Ruinen-Nacht nicht wie bisher: {r}'

@test
async def dschungel_hintergrund_tag_nacht(g):
    """Dschungel-Paket A–C: Dschungel-Tag mit grünem Himmel und Wind (Pflanzen wiegen sich), Nacht dunkelblau (Ebenen beim
    Vorzeichnen eingefärbt, Riesenblätter leuchten), ohne bisherige Nacht-Abdunklung; Wind und Nacht-Licht lassen sich
    abschalten (localStorage), dann wird still gezeichnet; nichts davon ändert Spielzustand."""
    G = ground
    fehler = []; g.p.on('pageerror', lambda e: fehler.append(str(e)))
    for zeit in ('mittag', 'nacht'):
        await g.load(level([G(0, 680, 4000), G(600, 520, 200), G(1200, 440, 120, 240, 'wall')], {'x': 100, 'y': 680}, {'x': 60, 'y': 680},
                           welt='dschungel', tageszeit=zeit))
        await g.steps(10); await g.ev("menuScreen = 'pause'")
        r = await g.ev("""(() => { djSchalter.wind.an = true; djSchalter.licht.an = true; const vor = JSON.stringify([p1.x, p1.y, p2.x, p2.y, simSteps]);
          camPos = camX = 300; draw(); draw();
          const H2 = hgNacht() ? DJ.skyNacht : DJ.sky, himmel = Array.from(H2.getContext('2d').getImageData(H2.width/2, 2, 1, 1).data).slice(0, 3);
          // Wind: dieselbe Pflanze zu zwei Zeitpunkten anders gedreht (nur Zeichnen)
          const b = DJ.LY.near[3], w1 = djWind(b.x, 10), w2 = djWind(b.x, 11.3);
          const nacht = hgNacht(), nk = nacht ? DJ.kacheln['far@n'] : null;
          let blau = null; if(nk){ const d = nk.c.getContext('2d').getImageData(0, 0, nk.c.width, nk.c.height).data; let r = 0, b2 = 0, n = 0;
            for(let i = 0; i < d.length; i += 4*97) if(d[i+3] > 200){ r += d[i]; b2 += d[i+2]; n++; } blau = n ? b2 > r*1.3 : null; }
          return {stil: BG_STIL.name, himmel, wind: Math.abs(w1 - w2) > 0.01, licht: hgEigenesLicht(), dark: THEME.dark, nacht, blau,
                  leuchtblatt: nacht ? DJ.MUSH.every(m => m.glow && m.ns) : null, unveraendert: vor === JSON.stringify([p1.x, p1.y, p2.x, p2.y, simSteps])}; })()""")
        assert r['unveraendert'], f'{zeit}: Zeichnen hat Spielzustand verändert'
        assert r['wind'] and r['licht'], f'{zeit}: {r}'
        if zeit == 'mittag':
            assert r['stil'] == 'dschungelTag' and r['himmel'][1] > r['himmel'][0] and r['himmel'][1] > r['himmel'][2], f'Tag: Himmel nicht grün {r}'
        else:
            assert r['stil'] == 'dschungelNacht' and r['himmel'][2] > r['himmel'][0] and r['himmel'][2] > r['himmel'][1], f'Nacht: Grund nicht blau {r}'
            assert r['blau'] and r['leuchtblatt'], f'Nacht: Ebenen nicht eingefärbt / Riesenblätter ohne Leuchten {r}'
            assert r['dark'] > 0, 'Test erwartet ein Nacht-Thema mit eigener Abdunklung (die der neue Look ersetzt)'
        # Schalter für schwache Geräte: Wind aus -> stille Kacheln, Nacht-Licht aus -> ohne Schäfte/Nebel/ferne Pflanzen
        r2 = await g.ev("""(() => { const vorW = djSchalter.wind.an, vorL = djSchalter.licht.an; try { localStorage.setItem('monchichi.dschungelWind', 'aus'); localStorage.setItem('monchichi.dschungelNachtlicht', 'aus'); } catch(e){}
          djSchalter.wind.an = null; djSchalter.licht.an = null; draw();
          const r = {wind: djAn(djSchalter.wind), licht: djAn(djSchalter.licht), kacheln: Object.keys(DJ.kacheln).filter(k => k.startsWith('near')).length};
          try { localStorage.removeItem('monchichi.dschungelWind'); localStorage.removeItem('monchichi.dschungelNachtlicht'); } catch(e){}
          djSchalter.wind.an = vorW; djSchalter.licht.an = vorL; return r; })()""")
        assert r2['wind'] is False and r2['licht'] is False and r2['kacheln'] >= 1, f'{zeit}: Schalter wirken nicht {r2}'
        await g.ev("menuScreen = null")
    assert not fehler, f'Fehler beim Zeichnen: {fehler}'

@test
async def neue_figuren_kante_wackeln(g):
    """Kante (Nutzerwunsch): Steht der Fuß (Mitte ± KANTE_FUSS) nicht mehr auf dem Boden, rutscht eine stehende Figur ab
    und fällt; steht er noch halb drauf, bleibt sie stehen. Wackeln (Pose „kante“: auf einem Fuß, Arme wedeln, Blick zum
    Abgrund) nur, wenn sie an die Kante GELAUFEN ist – nicht nach einer Landung. Wer normal läuft, fällt einfach runter."""
    await g.load(level([ground(0, 560, 600, 160), ground(800, 560, 600, 160)], {'x': 603, 'y': 560}, {'x': 797, 'y': 560}))
    await g.steps(60)
    r = await g.ev("""(() => { const e = {x1: p1.x, x2: p2.x, g1: p1.grounded, g2: p2.grounded};
      draw(); draw(); e.k1 = p1._ff && p1._ff.key;                         // gelandet/hingestellt: kein Wackeln
      p1._ff.gelaufen = true; p2._ff.gelaufen = true; p1._moveDir = 0; p2._moveDir = 0;
      const vor = JSON.stringify([p1.x, p1.y, p2.x, p2.y]);
      draw(); draw(); e.k1b = p1._ff.key; e.k2b = p2._ff.key; e.f1 = p1._ff.gelaufen;
      e.gleich = vor === JSON.stringify([p1.x, p1.y, p2.x, p2.y]); return e; })()""")
    assert r['x1'] == 603 and r['x2'] == 797 and r['g1'] and r['g2'], f'Fuß halb auf dem Boden: muss stehen bleiben {r}'
    assert r['k1'] != 'kante', f'nach dem Hinstellen/Landen kein Wackeln: {r}'
    assert r['k1b'] == 'kante' and r['k2b'] == 'kante' and r['gleich'], f'an die Kante gelaufen: Wackeln {r}'
    # Fuß ganz über dem Abgrund: rutscht ab und fällt
    await g.ev("p1.x = 610; p1._px = 610; p1.vx = 0; p2.x = 789; p2._px = 789; p2.vx = 0")
    await g.steps(40)
    r = await g.ev("({y1: p1.y, y2: p2.y, x1: p1.x, x2: p2.x})")
    assert r['y1'] > 600 and r['y2'] > 600 and r['x1'] > 610 and r['x2'] < 789, f'Fuß in der Luft, aber nicht gefallen: {r}'
    # mitten auf dem Boden: normale Steh-Pose, kein Abrutschen
    await g.ev("p1.x = 300; p1._px = 300; p1.y = 560; p1._py = 560; p1.vx = p1.vy = 0")
    await g.steps(40)
    r = await g.ev("({x: p1.x, k: p1._ff.key, r: kanteRichtung(p1, KANTE_WACKEL_RAND)})")
    assert r['x'] == 300 and r['k'] != 'kante' and r['r'] == 0, f'mitten auf dem Boden: {r}'

@test
async def muenzen_greifen_grosszuegig(g):
    """Münzen (Nutzerwunsch): zählen schon bei leichter Berührung der gezeichneten Figur (nicht erst, wenn man halb
    drinsteht), auch am Seil (Affe hängt gezeichnet unter dem Seil-Ende) und bei schnellen Bewegungen (Dash) – der Weg
    wird in Teilschritten abgefahren. Nach Neustart/Test-Sprung wird nichts unterwegs eingesammelt."""
    coins = [{'x': 433, 'y': 658}, {'x': 450, 'y': 658}]
    await g.load(level([ground(0, 680, 3000)], {'x': 400, 'y': 680}, {'x': 100, 'y': 680}, coins=coins))
    await g.steps(10)
    r = await g.ev("""(() => { menuScreen = 'pause';
      const P = p1, frei = () => { for(const c of coins){ c.taken = false; } P._muenzX = undefined; };
      const setze = (x, y) => { coins[0].x = x; coins[0].y = y; coins[1].x = 9000; frei(); updateCoins([P]); return coins[0].taken; };
      const x = P.x, y = P.y, e = {};
      e.rand = setze(x + 33, y - 22);         // Rand der gezeichneten Figur
      e.weit = setze(x + 52, y - 22);         // deutlich daneben: nicht
      e.oben = setze(x, y - 56);              // über dem Kopf (Rand)
      // Seil: Affe hängt gezeichnet links unter dem Seil-Ende (Anker rechts oben)
      const vor = {h: P.hookAttached, a: P.anchor, f: P.facing};
      P.hookAttached = true; P.anchor = {x: x + 60, y: y - 200}; P.facing = 1;
      e.seil = setze(x - 28, y + 4);
      P.hookAttached = vor.h; P.anchor = vor.a; P.facing = vor.f;
      // schneller Weg: Münze liegt nur zwischen alter und neuer Stelle
      coins[0].x = x - 42; coins[0].y = y - 22; frei(); P._muenzX = x - 60; P._muenzY = y - 22; P.vx = 44; updateCoins([P]); e.weg = coins[0].taken;
      // Sprung ohne passendes Tempo (Neustart/Test-Sprung): nicht abfahren
      frei(); P._muenzX = x - 88; P._muenzY = y - 22; P.vx = 0; updateCoins([P]); e.teleport = coins[0].taken;
      frei(); menuScreen = null; return e; })()""")
    assert r == {'rand': True, 'weit': False, 'oben': True, 'seil': True, 'weg': True, 'teleport': False}, f'Münzen greifen: {r}'

@test
async def dschungel_wind_anlaufzeit(g):
    """Wind-Abschaltung (Nutzerwunsch „Warum weht kein Wind?“): In den ersten DJ_ANLAUF_MS nach dem Levelstart, bei
    einzelnen Aussetzern ab DJ_LUECKE_MS (Tab-Wechsel) und im Menü zählen langsame Bilder nicht; danach schalten
    4 langsame Bilder hintereinander den Wind weiterhin ab. Die Leistungsanzeige (F) zeigt den Zustand."""
    await g.load(level([ground(0, 680, 3000)], {'x': 100, 'y': 680}, {'x': 60, 'y': 680}, welt='dschungel', tageszeit='mittag'))
    await g.steps(5)
    r = await g.ev("""(() => { const S = djSchalter.wind; S.an = true; S.n = 0; S.summe = 0; S.lang = 0;
      djMessLevel = null; for(let i = 0; i < 10; i++) djMessen(S, 120);   // Levelstart: viel Vorzeichnen
      const anlauf = S.an;
      djAnlaufBis = 0; for(let i = 0; i < 10; i++) djMessen(S, 500);    // Tab-Wechsel / einzelne lange Lücken
      const luecke = S.an;
      menuScreen = 'pause'; for(let i = 0; i < 10; i++) djMessen(S, 120); menuScreen = null;
      const menue = S.an, text = djStatusText();
      for(let i = 0; i < 4; i++) djMessen(S, 120);                        // danach wirklich langsam -> aus
      const r = {anlauf, luecke, menue, text, danach: S.an, text2: djStatusText()};
      S.an = true; S.n = 0; S.summe = 0; S.lang = 0; return r; })()""")
    assert r['anlauf'] and r['luecke'] and r['menue'], f'Wind zu früh aus: {r}'
    assert r['danach'] is False, f'Wind bleibt trotz langsamer Bilder an: {r}'
    assert 'Wind: an' in r['text'] and 'Wind: aus' in r['text2'], f'Anzeige falsch: {r}'

@test
async def boden_dekor_dschungel(g):
    """boden-dekor-paket (a)+(c): bei JEDER Dschungel-Auswahl (Morgen, Mittag, Abend, Nacht) ist Boden-Dekor gezeichnet –
    Dickicht, feines Gras/Büschel, Farnbusch/Blume/Pilz (Pixelprobe über der Oberseite gegen ein Bild ohne Dekor) – und
    die Hintergrund-Tiere laufen (Schnecken am Stamm, ferne Schmetterlinge/Nachtfalter). Leuchtkreise, Schwebesamen und
    nächtliche Lichtschäfte sind aus. Zeichnen ändert keinen Spielzustand."""
    teile = [ground(0, 680, 6000), ground(1600, 520, 400), ground(2600, 440, 240, 240, 'wall')]
    srv = webserver(); await g.p.goto(srv.url + 'index.html'); await g.p.wait_for_timeout(400)   # Leinwand lesbar (nicht file://)
    assert not await g.ev("DJ_LEUCHTKREISE || DJ_SCHWEBESAMEN || DJ_LICHTSTRAHLEN"), 'Leuchtkreise/Schwebesamen/Lichtstrahlen sollen aus sein'
    for zeit in ('morgen', 'mittag', 'abend', 'nacht'):
        await g.load(level(teile, {'x': 100, 'y': 680}, {'x': 60, 'y': 680}, welt='dschungel', tageszeit=zeit))
        await g.steps(10); await g.ev("menuScreen = 'pause'")
        r = await g.ev("""(() => { const vor = JSON.stringify([p1.x, p1.y, p2.x, p2.y, simSteps]);
          const e = {stil: BG_STIL && BG_STIL.name, tiere: hgTierRegeln(), an: bodenDekorAn()};
          bodenBereit(); e.dickicht = BODEN.dickicht.length; e.gras = BODEN.stuecke.length; e.gross = BODEN.gross.length;
          e.arten = [...new Set(BODEN.gross.map(g => g.art))].sort();
          // Pixelprobe: Streifen knapp über der Oberseite mit und ohne Dekor
          p1.x = p2.x = 9000; p1._px = p2._px = 9000; camPos = camX = 800; djSchalter.wind.an = false;
          const cv = document.querySelector('canvas'), c2 = cv.getContext('2d'), k = cv.width / W;
          const streifen = () => { draw(); return c2.getImageData(0, Math.floor(cv.height*0.80), cv.width, Math.floor(cv.height*0.12)).data; };   // Streifen knapp über dem Boden
          const mit = streifen(); const alt = window.bodenDekorAn; window.bodenDekorAn = () => false; const ohne = streifen(); window.bodenDekorAn = alt;
          let diff = 0; for(let i = 0; i < mit.length; i += 16) if(Math.abs(mit[i] - ohne[i]) + Math.abs(mit[i+1] - ohne[i+1]) + Math.abs(mit[i+2] - ohne[i+2]) > 30) diff++;
          e.anteil = +(diff / (mit.length/16)).toFixed(3);
          // Hintergrund-Tiere: Schnecken am Stamm / ferne Schmetterlinge setzen Bilder
          const orig = djtSetzen; let n = 0; window.djtSetzen = (...a) => { n++; return orig(...a); };
          let stamm = 0, flieger = 0;
          for(let t = 0; t < 120; t += 7){ for(const cx of [0, 1300, 2600, 3900]){ camX = cx; n = 0; djHgTiereStamm(t, hgNacht()); stamm += n; n = 0; djHgTiereFliegen(t, hgNacht()); flieger += n; } }
          window.djtSetzen = orig; e.stamm = stamm; e.flieger = flieger;
          p1.x = 100; p2.x = 60; p1._px = 100; p2._px = 60;
          e.gleich = vor === JSON.stringify([p1.x, p1.y, p2.x, p2.y, simSteps]); return e; })()""")
        await g.ev("menuScreen = null")
        assert r['tiere'] and r['an'], f'{zeit}: Boden-Dekor/Tiere nicht an {r}'
        assert r['dickicht'] > 50 and r['gras'] > 10 and r['gross'] > 3, f'{zeit}: zu wenig Dekor {r}'
        assert r['anteil'] > 0.05, f'{zeit}: Dekor kaum zu sehen {r}'
        assert r['stamm'] > 0 and r['flieger'] > 0, f'{zeit}: Hintergrund-Tiere fehlen {r}'
        assert r['gleich'], f'{zeit}: Zeichnen hat Spielzustand verändert'
    srv.shutdown()

@test
async def boden_dekor_freihalten(g):
    """boden-dekor-paket (b)+(d): große Pflanzen (Farnbusch, Blume, Pilz) 60 px auseinander, 45 px von der Kante, nicht
    am Start (260 px); nichts (Pflanze, Dickicht, Tier, Leuchtpflanze) in der Freihalte-Zone um Münzen, Stacheln, Hebel,
    Sprungpilze, Druckplatten, Haken, Checkpoint und Ziel (60 px links/rechts, 90 px senkrecht); kein Boden-Tier innerhalb
    von ±34 px einer großen Pflanze, keine Leuchtpflanze innerhalb von 60 px."""
    teile = [ground(0, 680, 9000), ground(1400, 520, 600), ground(3000, 480, 800), ground(5200, 560, 1200)]
    obj = dict(coins=[{'x': x, 'y': 660} for x in range(700, 8800, 900)],
               spikes=[{'x': 2200, 'y': 640, 'w': 40, 'h': 40, 'dir': 0}, {'x': 6000, 'y': 520, 'w': 40, 'h': 40, 'dir': 0}],
               switches=[{'x': 3300, 'y': 460, 'link': 1}], checkpoints=[{'x': 4200, 'y': 680}], hooks=[{'x': 2600, 'y': 560}],
               bouncers=[{'x': 4800, 'y': 680}], plates=[{'x': 7000, 'y': 680, 'link': 2}], goal={'x': 8700, 'y': 680})
    for zeit in ('mittag', 'nacht'):
        await g.load(level(teile, {'x': 100, 'y': 680}, {'x': 60, 'y': 680}, welt='dschungel', tageszeit=zeit, **obj))
        await g.steps(10)
        r = await g.ev("""(() => { critFor = null; decoFor = null; bodenFor = null; djPwFor = null; buildDeco(); buildCritters(); bodenBereit();
          const P = bodenFreihaltePunkte(), sperr = bodenSperre(), G = BODEN.gross, f = [];
          const inZone = (x, y) => P.some(([px, py]) => Math.abs(px - x) < 60 && Math.abs(py - y) < 90);
          for(const g of G){ const y = g.boden !== undefined ? g.boden : g.y;
            if(inZone(g.x, y) || sperr(g.x, y)) f.push('Pflanze in Zone ' + g.art + '@' + Math.round(g.x));
            if(bodenNahStart(g.x)) f.push('Pflanze am Start @' + Math.round(g.x));
            const z = BODEN.zellen.find(z => z.y === y && g.x >= z.x - 1 && g.x <= z.x + 41);
            if(z && (g.x - z.lauf.x0 < 45 || z.lauf.x1 - g.x < 45)) f.push('Pflanze an der Kante @' + Math.round(g.x)); }
          for(let i = 0; i < G.length; i++) for(let j = i + 1; j < G.length; j++)
            if(Math.abs(G[i].x - G[j].x) < 60 && Math.abs(G[i].y - G[j].y) < 60) f.push('Pflanzen zu dicht @' + Math.round(G[i].x));
          for(const d of BODEN.dickicht) if(inZone(d.x, d.y - 10)) f.push('Dickicht in Zone @' + Math.round(d.x));
          for(const c of critters){ const y = c.hy !== undefined ? c.hy + 50 : c.y;
            if(c.kind !== 'sloth' && c.kind !== 'bat' && inZone(c.x, y)) f.push('Tier in Zone ' + c.kind + '@' + Math.round(c.x));
            if(c.pl && G.some(g => Math.abs(g.x - c.x) < 34 && Math.abs((g.boden !== undefined ? g.boden : g.y) - c.y) < 60)) f.push('Tier an Pflanze ' + c.kind + '@' + Math.round(c.x));
            if(c.pl && bodenNahStart(c.x)) f.push('Tier am Start'); }
          for(const b of birds) if(inZone(b.homeX, b.homeY) || G.some(g => Math.abs(g.x - b.homeX) < 34 && Math.abs((g.boden !== undefined ? g.boden : g.y) - b.homeY) < 60)) f.push('Vogel @' + b.homeX);
          for(const p of hgLeuchtpflanzen()){ if(inZone(p.wx, p.wy)) f.push('Leuchtpflanze in Zone @' + Math.round(p.wx));
            if(G.some(g => Math.abs(g.x - p.wx) < 60)) f.push('Leuchtpflanze an Pflanze @' + Math.round(p.wx)); }
          return {f: f.slice(0, 12), gross: G.length, tiere: critters.length, leucht: hgLeuchtpflanzen().length}; })()""")
        assert not r['f'], f'{zeit}: {r}'
        assert r['gross'] > 5, f'{zeit}: zu wenig große Pflanzen {r}'

@test
async def dschungel_tiere_regeln(g):
    """Dschungel-Paket D: deutlich weniger Tiere (Regeln aus DK.build): Boden-Tiere nie in Materialien (frei ±34 px, 46 px
    hoch, 45 px vom Rand), Frosch/Schnecke mit mind. 70 px Laufstrecke, Boden-Tiere weit auseinander, Faultier höchstens
    alle 1300 px; Vögel sitzen auf Oberseiten fester Flächen und fliegen NICHT weg; nachts Schnecke statt Frosch."""
    G = ground
    teile = [G(0, 680, 9000)] + [G(x, 600, 80, 80, 'wall') for x in range(900, 9000, 1100)] + [G(x, 400, 320) for x in range(500, 9000, 1500)]
    for zeit in ('mittag', 'nacht'):
        await g.load(level(teile, {'x': 100, 'y': 680}, {'x': 60, 'y': 680}, welt='dschungel', tageszeit=zeit, goal={'x': 8900, 'y': 680}))
        await g.steps(5)
        r = await g.ev("""(() => { critFor = null; decoFor = null; buildDeco(); buildCritters();
          const fest = solids.filter(o => !o.gone && o.type !== 'oneway');
          const imMaterial = critters.filter(c => ['frog', 'snail', 'mush', 'bud'].includes(c.kind) && fest.some(o => c.x + 33 > o.x && c.x - 33 < o.x + o.w && c.y - 45 < o.y + o.h && c.y - 2 > o.y));
          const boden = critters.filter(c => ['frog', 'snail', 'mush', 'bud'].includes(c.kind)).sort((a, b) => a.x - b.x);
          let minAbstand = 1e9; for(let i = 1; i < boden.length; i++) if(boden[i].y === boden[i-1].y) minAbstand = Math.min(minAbstand, boden[i].x - boden[i-1].x);
          const laeufer = critters.filter(c => c.minX !== undefined), kurz = laeufer.filter(c => c.maxX - c.minX < 70);
          const haenger = critters.filter(c => c.kind === 'sloth' || c.kind === 'bat').map(c => c.x).sort((a, b) => a - b);
          let minH = 1e9; for(let i = 1; i < haenger.length; i++) minH = Math.min(minH, haenger[i] - haenger[i-1]);
          const voegel = birds.map(b => ({x: b.x, y: b.y, bleibt: b.bleibt, oben: !decoSolidAt(b.x, b.y - 2) && solids.some(s => s.y === b.y && b.x >= s.x && b.x <= s.x + s.w)}));
          const neu = critters.length; window.__alt = hgTierRegeln; window.hgTierRegeln = () => false; critFor = null; decoFor = null; buildDeco(); buildCritters();
          const alt = critters.length; window.hgTierRegeln = __alt; critFor = null; decoFor = null; buildDeco(); buildCritters();
          return {imMaterial: imMaterial.map(c => c.kind + '@' + Math.round(c.x)), minAbstand, kurz: kurz.length, minH, voegel, neu, alt,
                  froesche: critters.filter(c => c.kind === 'frog').length, nacht: hgNacht()}; })()""")
        assert not r['imMaterial'], f'{zeit}: Tiere in Materialien {r["imMaterial"]}'
        assert r['minAbstand'] >= 400, f'{zeit}: Boden-Tiere zu dicht {r["minAbstand"]}'
        assert r['kurz'] == 0 and r['minH'] >= 1300, f'{zeit}: {r}'
        assert r['neu'] < r['alt']*0.7, f'{zeit}: nicht deutlich weniger Tiere ({r["neu"]} statt {r["alt"]})'
        assert r['voegel'] and all(v['bleibt'] and v['oben'] for v in r['voegel']), f'{zeit}: Vögel {r["voegel"]}'
        if zeit == 'nacht': assert r['nacht'] and r['froesche'] == 0, f'nachts Frosch statt Schnecke: {r}'
        # Vögel fliegen nicht weg, auch wenn eine Figur ganz nah ist
        b0 = r['voegel'][0]
        await g.ev(f"p1.x = {b0['x']} - 30; p1.y = {b0['y']}; p1.vx = 0")
        await g.steps(30)
        st = await g.ev(f"birds.find(b => b.homeX === {b0['x']}).state")
        assert st == 'sit', f'{zeit}: Vogel fliegt weg ({st})'

@test
async def dschungel_leuchtpflanzen(g):
    """Dschungel-Paket C: Leuchtpflanzen am Boden nur nachts, nur auf Oberseiten fester Erd-Flächen (Breite >= 60, nicht
    an der Decke, nicht in einer anderen Fläche), kleine Flächen höchstens 1–2 Pflanzen, große mit 260–780 px Abstand,
    keine zwei gleichen Arten nebeneinander; nicht an Hebeln/Münzen."""
    G = ground
    teile = [G(0, 680, 6000), G(800, 640, 600, 40), G(1600, 480, 80), G(2000, 480, 300), G(2600, 520, 40), G(3000, 30, 400)]
    await g.load(level(teile, {'x': 100, 'y': 680}, {'x': 60, 'y': 680}, welt='dschungel', tageszeit='nacht',
                       switches=[{'x': 4000, 'y': 660, 'link': 1}], coins=[{'x': 4600, 'y': 660}]))
    await g.steps(5)
    r = await g.ev("""(() => { djPwFor = null; const pw = hgLeuchtpflanzen();
      const auf = p => solids.find(s => s.type === 'ground' && s.y === p.wy && p.wx >= s.x && p.wx <= s.x + s.w);
      const fehl = pw.filter(p => { const s = auf(p); return !s || s.w < 60 || s.y <= 40 || decoSolidAt(p.wx, p.wy - 6); });
      const proFlaeche = {}; for(const p of pw){ const s = auf(p); if(s){ const k = s.x + ',' + s.y + ',' + s.w; (proFlaeche[k] = proFlaeche[k] || []).push(p.wx); } }
      const zuViel = Object.entries(proFlaeche).filter(([k, xs]) => { const w = +k.split(',')[2]; return w <= 400 && xs.length > (w > 260 ? 2 : 1); });
      let gleich = 0; for(let i = 1; i < pw.length; i++) if(pw[i].k === pw[i-1].k) gleich++;
      let eng = 0; for(const xs of Object.values(proFlaeche)){ xs.sort((a, b) => a - b); for(let i = 1; i < xs.length; i++) if(xs[i] - xs[i-1] < 200) eng++; }
      const anHebel = pw.filter(p => Math.abs(p.wx - 4000) < 160 || Math.abs(p.wx - 4600) < 40).length;
      const tag = (() => { const alt = BG_STIL; BG_STIL = Object.assign({}, alt, {nacht: false}); const n = hgLeuchtpflanzen().length; BG_STIL = alt; return n; })();
      return {n: pw.length, fehl: fehl.length, zuViel, gleich, eng, anHebel, tag}; })()""")
    assert r['n'] >= 4, f'zu wenige Leuchtpflanzen: {r}'
    assert r['fehl'] == 0 and not r['zuViel'] and r['gleich'] == 0 and r['eng'] == 0 and r['anHebel'] == 0, f'Leuchtpflanzen falsch verteilt: {r}'
    assert r['tag'] == 0, 'Leuchtpflanzen am Tag'

@test
async def broeckel_und_durchbruch_ecken(g):
    """Nutzerwunsch: (1) grenzt Wand/Boden an eine Durchbruch-Wand, gibt es dort keine runde Ecke (sie zählt als Nachbar);
    (2) Bröckelboden: an freien Ecken wirklich rund (Ecke durchsichtig), oben gelbes trockenes Gras, nichts über der Outline;
    (3) Durchbruch-Wand frei hängend rund, auf dem Boden stehend unten gerade."""
    G = ground
    await g.load(level([G(0, 680, 2000), G(200, 360, 80, 160, 'wall'), G(200, 520, 80, 80, 'bruch'), G(700, 480, 160, 40, 'crumble'),
                        G(1000, 400, 40, 40, 'bruch'), G(1200, 600, 40, 80, 'bruch')],
                       {'x': 100, 'y': 680}, {'x': 60, 'y': 680}))
    await g.steps(3)
    r = await g.ev("""(() => { matRasterHolen(); const unten = Tn(5, 13), frei = Tn(4, 12);
      const c = broeckelKachel(17, 12), q = c.getContext('2d'), px = (x, y) => Array.from(q.getImageData(x, y, 1, 1).data);
      // Kachel 80×88 (2-fach, 4 px Gras darüber): linke obere Ecke frei -> rund (durchsichtig); oben in der Mitte Gras
      return {unten, frei, ecke: px(1, 9)[3], gras: px(40, 12), ueber: px(40, 5)[3],
              haengt: kachelRad(25, 10), steht: [kachelRad(30, 15), kachelRad(30, 16)]}; })()""")
    assert r['unten'] and not r['frei'], f'Durchbruch-Wand zählt nicht als Nachbar: {r}'
    assert r['ecke'] < 40, f'Bröckelboden-Ecke nicht rund: {r}'
    gr = r['gras']; assert gr[3] > 200 and gr[0] > 150 and gr[1] > 130 and gr[2] < gr[1], f'kein gelbes Gras oben: {r}'
    assert r['ueber'] < 10, f'Gras ragt über die Outline hinaus: {r}'
    assert r['haengt'] == [9, 9, 9, 9], f'frei hängende Durchbruch-Wand nicht rund: {r}'
    assert r['steht'] == [[9, 9, 0, 0], [0, 0, 0, 0]], f'auf dem Boden stehende Durchbruch-Wand unten nicht gerade: {r}'

@test
async def welt_details_und_vordergrund(g):
    """Design-Politur D: jede Welt bekommt ihre Details (Ruinen: Fackeln, Höhle: Tropfsteine mit Tropfen, Dschungel:
    Wasserfall mit Regenbogen, Vulkan: Asche/Funken). Ein dunkler Vordergrund am unteren Bildrand gibt es NICHT mehr
    (Nutzerwunsch: „was soll diese zusätzliche untere Reihe mit Schatten“)."""
    srv = webserver(); kx = await g.p.context.browser.new_context(viewport={'width': 1280, 'height': 720}); p = await kx.new_page(); g = Game(p)
    try:
        await p.goto(srv.url + 'index.html'); await p.wait_for_function("GameMenu.levelsReady()", timeout=8000); await p.wait_for_timeout(800)
        await startmenue_bis_level(g)
        for welt, datei, spalte in LEISTUNG_STELLEN:
            await koop_level(g, datei)
            r = await g.ev(f"""(() => {{ setTheme(composeLook('{welt}', 'mittag')); return {{welt: detailWelt, fackeln: BG_FACKELN.length, tropfen: BG_TROPFEN.length,
                ebene: BG_LAYERS.includes(detailEbene), vorne: typeof vordergrundZeichnen === 'function', stil: BG_STIL && BG_STIL.name}}; }})()""")
            if welt == 'dschungel':   # Dschungel-Paket: eigener neuer Hintergrund (ohne Wasserfall) statt der alten Ebenen mit Details
                assert r['stil'] == 'dschungelTag', f'{welt}: neuer Dschungel-Hintergrund fehlt {r}'
            else:
                assert r['welt'] == welt and r['ebene'] and not r['stil'], f'{welt}: Details fehlen {r}'
            assert not r['vorne'], 'Vordergrund-Schatten unten ist wieder da'
            if welt == 'ruinen': assert r['fackeln'] > 0, r
            if welt == 'hoehle': assert r['tropfen'] > 0, r
    finally:
        await kx.close(); srv.shutdown()

# Ruckeln (Design-Politur 2): Obergrenze für einen Spielschritt (ms) in den teuersten Leveln. Vorher kostete die
# Licht- und Fallen-Berechnung im Sonnentempel/Fallengang 15–26 ms je Schritt (54 Schritte je Sekunde -> Ruckeln).
SPIELSCHRITT_MS_GRENZE = 6
@test
async def spielschritt_schnell(g):
    """Ruckeln behoben (Design-Politur 2): Lichtstrahl und Flammen prüfen feste Teile über ein Raster-Verzeichnis statt
    jedes Teil des Levels – ein Spielschritt dauert auch in den Licht-/Fallen-Leveln höchstens SPIELSCHRITT_MS_GRENZE ms;
    der Lichtweg ist derselbe wie mit der alten Prüfung (jedes Kästchen verglichen)."""
    for datei in ('ruinen/04-sonnentempel.json', 'ruinen/03-fallengang.json', 'vulkan/05-schlackewerk.json'):
        await koop_level(g, datei)
        ms = await g.ev("(() => { for(let i = 0; i < 5; i++) stepSim(performance.now()); const t0 = performance.now(); for(let i = 0; i < 60; i++) stepSim(performance.now()); return (performance.now() - t0)/60; })()")
        assert ms <= SPIELSCHRITT_MS_GRENZE, f'{datei}: Spielschritt {ms:.1f} ms (Grenze {SPIELSCHRITT_MS_GRENZE})'
        gleich = await g.ev("""(() => { const alt = (c, r) => { const px = c*40 + 20, py = r*40 + 20;
            return solids.some(s => !s.gone && s.type !== 'oneway' && s.type !== 'fake' && s.type !== 'lichtquelle' && px >= s.x && px < s.x + s.w && py >= s.y && py < s.y + s.h); };
          const altF = (px, py) => solids.some(s => !s.gone && s.type !== 'oneway' && s.type !== 'fake' && px >= s.x && px < s.x + s.w && py >= s.y && py < s.y + s.h);
          let n = 0, falsch = 0; const cmax = Math.ceil(LEVEL_W/40);
          for(let c = -1; c <= cmax; c++) for(let r = -4; r <= 18; r++){ n++; if(alt(c, r) !== lichtFestImSpiel(c, r)) falsch++;
            const px = c*40 + 7, py = r*40 + 29; if(altF(px, py) !== falleFestBei(px, py)) falsch++; }
          return {n, falsch}; })()""")
        assert gleich['falsch'] == 0, f'{datei}: Raster-Prüfung weicht ab: {gleich}'

@test
async def leinwand_scharf_und_schnell(g):
    """Design-Politur A: bei doppelter Pixeldichte (DPR 2) hat die Leinwand echte 2560×1440 Pixel (RS = 2, scharf statt
    hochskaliert), bei 4K-Dichte bis LEINWAND_MAX_BREITE; ein Bild zu zeichnen dauert in jeder Welt am Tag und in der
    Nacht höchstens ZEICHNEN_MS_GRENZE ms (früher kostete die Dunkel-Schicht bei DPR 2 rund 90 ms)."""
    srv = webserver(); seite = await g.p.context.browser.new_page(viewport={'width': 1280, 'height': 720}, device_scale_factor=2)
    try:
        await seite.goto(srv.url + 'index.html'); await seite.wait_for_function("GameMenu.levelsReady()", timeout=8000); await seite.wait_for_timeout(800)
        g2 = Game(seite); await startmenue_bis_level(g2)
        r = await g2.ev("(() => { fitCanvasRes(); return {w: cvs.width, h: cvs.height, rs: RS, max: LEINWAND_MAX_BREITE}; })()")
        assert r['w'] == 2560 and r['h'] == 1440 and r['rs'] == 2 and r['max'] >= 3840, f'Leinwand bei DPR 2: {r}'
        v = await g2.ev("(() => { const b = cvs.getBoundingClientRect(); return Math.abs((cvs.width/cvs.height)/(b.width/b.height) - 1); })()")
        assert v < 0.01, f'Spielbild verzerrt (Seitenverhältnis weicht um {v:.2%} ab)'
        zeiten = {}
        for welt, datei, spalte in LEISTUNG_STELLEN:
            await koop_level(g2, datei)
            for zeit in ('mittag', 'nacht'):
                await g2.ev(f"""(() => {{ menuScreen = null; p1.x = {spalte}*40 + 60; p2.x = {spalte}*40 + 20; p1.y = p2.y = 100;
                    camPos = camX = {spalte}*40 - 200; setTheme(composeLook('{welt}', '{zeit}')); }})()""")
                await g2.steps(20); await g2.ev("menuScreen = 'pause'")
                zeiten[f'{welt}-{zeit}'] = await g2.ev("(() => { draw(); draw(); const t0 = performance.now(); for (let i = 0; i < 10; i++) draw(); return (performance.now() - t0)/10; })()")
                await g2.ev("menuScreen = null")
        langsam = {k: round(v, 1) for k, v in zeiten.items() if v > ZEICHNEN_MS_GRENZE}
        assert not langsam, f'Zeichnen zu langsam (Grenze {ZEICHNEN_MS_GRENZE} ms): {langsam}; alle: {zeiten}'
    finally:
        await seite.close(); srv.shutdown()

@test
async def musik_und_ambiente(g):
    """Klaviermusik: Takte in F-Dur, beim Regenbogen heller (höher); Klavier/Wind/Grillen/Bach werden vorberechnet."""
    st = await g.ev("""(()=>{ const out={}; const it=musicBuild(new OfflineAudioContext(2,44100,44100), out); while(!it.next().done){}
      mus.motif = null; const normal=[], bright=[];
      for(let b=0;b<16;b++){ normal.push(...musicCompose(b,false)); }
      mus.motif = null; for(let b=0;b<16;b++){ bright.push(...musicCompose(b,true)); }
      const F = [5,7,9,10,0,2,4];
      const inKey = [...normal, ...bright].every(e => F.includes(((e.midi%12)+12)%12));
      const avg = a => a.filter(e=>e.midi>=60).reduce((s,e)=>s+e.midi,0)/Math.max(1,a.filter(e=>e.midi>=60).length);
      return {piano:Object.keys(out.piano).length, amb:!!(out.wind&&out.crickets&&out.brook), n:normal.length, inKey, up: avg(bright)-avg(normal)}; })()""")
    assert st['piano'] == 4 and st['amb'] and st['n'] > 100, f'Musik/Ambiente fehlt: {st}'
    assert st['inKey'], 'Töne außerhalb von F-Dur'
    assert st['up'] > 8, f'Regenbogen-Musik nicht heller: {st}'
    await g.p.keyboard.press('KeyF'); await g.p.keyboard.press('KeyF')
    if await g.ev("audioCtx && audioCtx.state === 'running'"):
        for _ in range(60):   # Musik wird im Hintergrund berechnet – langsame Rechner brauchen länger (bis 30 s)
            if await g.ev("mus.ready && mus.log.length > 0"): break
            await g.p.wait_for_timeout(500)
        assert await g.ev("mus.ready && mus.log.length > 0"), 'Musik spielt nicht'

@test
async def eigene_aufnahmen(g):
    """Eigene Aufnahmen: Vögel/Regen/Fluss laufen als nahtlose Schleife, Musik streamt, blendet ein,
    blendet beim Tod aus und startet nach dem Weitermachen von vorne."""
    srv = webserver(); p = g.p
    try:
        await p.goto(srv.url + 'index.html'); await p.wait_for_timeout(300)
        await startmenue_bis_level(g)   # Ton freischalten + über das Startmenü ins Level
        if not await g.ev("audioCtx && audioCtx.state === 'running'"):
            return   # ohne Tonausgabe (manche Testumgebungen) nichts zu prüfen
        for _ in range(30):
            if await g.ev("fileAudio.ok.birds && fileAudio.ok.rain && fileAudio.ok.river && fileAudio.ok.music"): break
            await p.wait_for_timeout(500)
        ok = await g.ev("({...fileAudio.ok})")
        assert ok.get('birds') and ok.get('rain') and ok.get('river'), f'Schleifen nicht geladen: {ok}'
        assert ok.get('music'), f'Musik spielt nicht: {ok}'
        # nahtlose Schleife: Anfang/Ende ohne Stille
        assert await g.ev("""(()=>{ const src = audioCtx.createBuffer(2, 44100*4, 44100);
            for(let c=0;c<2;c++){ const d=src.getChannelData(c); for(let i=0;i<d.length;i++) d[i]=Math.random()*0.4-0.2; }
            const b = fileLoopBuffer(audioCtx, src, 1); const d = b.getChannelData(0);
            return Math.abs(b.length - 44100*3) < 50 && Math.abs(d[0]) < 0.25; })()"""), 'Schleife kaputt'
        await p.wait_for_timeout(3000)
        t1 = await g.ev("fileAudio.el.currentTime")
        assert t1 > 1, f'Musik läuft nicht weiter: {t1}'
        # Tod -> ausblenden; weitermachen -> von vorne
        await g.ev("die(p1)"); await p.wait_for_timeout(1500)
        assert await g.ev("fileAudio.gain.gain.value") < 0.05, 'Musik blendet beim Tod nicht aus'
        await p.keyboard.press('KeyA'); await p.wait_for_timeout(2600)
        assert await g.ev("fileAudio.el.currentTime") < 3, 'Musik startet nach dem Tod nicht von vorne'
    finally:
        srv.shutdown()

@test
async def seil_abflug_mit_schwung(g):
    """Vom Seil loslassen (Springen) mit Schwung: Affe fliegt weit weiter, auch ohne Taste (kein Abbremsen auf 7,2).
    (Schritt für Schritt im festen Takt – unabhängig davon, wie schnell der Rechner ist; Liane 2 seit Nutzerwunsch.)"""
    await g.load(level([ground(0, 680, 4000)], {'x': 900, 'y': 680}, {'x': 860, 'y': 680}, hooks=[{'x': 1000, 'y': 250, 'radius': 260}]))
    r = await g.ev("""(() => { menuScreen = 'pause'; let ts = 5e6; const h = hooks[0], P = p1;
      const st = () => { stepSim(ts += 1000/54); for(const k in KEYS) if(k.endsWith('_pressed')) KEYS[k] = false; };
      P.x = h.x - 60; P.y = h.y + 170 + P.h*0.6; P.vx = 11; P.vy = 0; P.grounded = false; P._px = P.x; P._py = P.y;
      P.hookAttached = true; P.ropeWasAirborne = true; P.anchor = h; P.ropeLen = 180; P.ropeMax = 220; KEYS.KeyG = true;
      for(let i = 0; i < 3; i++) st();
      KEYS.Space = true; KEYS.Space_pressed = true; st(); KEYS.Space = false; KEYS.KeyG = false;
      const a = {hook: P.hookAttached, vx: P.vx, x: P.x};
      for(let i = 0; i < 14; i++) st();
      menuScreen = null; return {a, b: {vx: P.vx, x: P.x, g: P.grounded}}; })()""")
    st, st2 = r['a'], r['b']
    assert not st['hook'], 'Springen löst das Seil nicht'
    assert st2['vx'] > 8 or st2['g'], f'Schwung nach dem Loslassen weg: {st} -> {st2}'
    assert st2['x'] - st['x'] > 100, f'Affe kommt nach dem Loslassen nicht nach vorne: {st} -> {st2}'

@test
async def liane_volle_laenge(g):
    """Liane-Länge beim Greifen. Nutzer-Rückmeldung (zurückgenommen): NICHT mehr sofort in die volle Reichweite fallen –
    LIANE_VOLLE_LAENGE = false: in der Luft gegriffen bleibt sie so lang wie der Abstand beim Greifen. Mit
    LIANE_VOLLE_LAENGE = true (alter Wunsch) gibt sie bis zur Reichweite nach, aber nie bis auf Boden, Stacheln, Lava oder
    in eine Flammen-Falle (LIANE_BODEN_ABSTAND)."""
    assert await g.ev("LIANE_VOLLE_LAENGE") is False
    await g.load(level([ground(0, 680, 900), ground(1300, 680, 900)], {'x': 300, 'y': 680}, {'x': 100, 'y': 680},
                       hooks=[{'x': 500, 'y': 200, 'radius': 260}, {'x': 1100, 'y': 400, 'radius': 400}],
                       spikes=[{'x': 1100, 'y': 680, 'w': 40, 'h': 40}]))
    r = await g.ev("""(() => { menuScreen = 'pause'; let ts = 5e6; const P = p1, e = {};
      const st = () => { stepSim(ts += 1000/54); for(const k in KEYS) if(k.endsWith('_pressed')) KEYS[k] = false; };
      const greif = (h, dx, dy) => { P.x = h.x + dx; P.y = h.y + dy + P.h*0.6; P.vx = 0; P.vy = 0; P.grounded = false; P.hookAttached = false; P.lianeSperre = 0;
        KEYS.KeyG = true; KEYS.KeyG_pressed = true; st(); const L = P.ropeLen; for(let i = 0; i < 60; i++) st(); return {L: Math.round(L), haengt: P.hookAttached, tot: !!deathState}; };
      e.frei = greif(hooks[0], 20, 50);      // viel Luft: volle Reichweite
      e.stacheln = greif(hooks[1], 20, 50);  // Stacheln 280 px darunter, Reichweite 400: kürzer
      KEYS.KeyG = false; menuScreen = null; return e; })()""")
    abst = round((20**2 + 50**2) ** 0.5)
    assert r['frei']['haengt'] and abs(r['frei']['L'] - abst) <= 2, f'Liane nicht so lang wie beim Greifen: {r}'
    s = r['stacheln']
    assert s['haengt'] and not s['tot'] and abs(s['L'] - abst) <= 2, f'Liane über den Stacheln: {r}'
    # Flammen-Falle nach oben im Boden unter dem Haken: die Liane bleibt über der Flamme (FLAMME_LAENGE Kästchen)
    await g.load(level([ground(0, 680, 2000)], {'x': 300, 'y': 680}, {'x': 100, 'y': 680}, hooks=[{'x': 1000, 'y': 200, 'radius': 400}],
                       traps=[{'x': 980, 'y': 640, 'art': 'flamme', 'richtung': 'o', 'takt': 2, 'versatz': 0}]))
    frei = await g.ev("lianeFreiUnten(hooks[0], p1) + hooks[0].y + p1.h*0.6")   # tiefste Füße
    assert frei < 640 - await g.ev('FLAMME_LAENGE')*40, f'Liane hängt in die Flamme: Füße bis {frei}'

@test
async def liane_von_oben(g):
    """Nutzer-Video „von oben reinspringen, der Haken flippt rum“: liegt die Hand über dem Haken (Seil steiler als
    LIANE_GRIFF_WINKEL), spannt sich die Liane erst, sobald er auf Hakenhöhe gefallen ist (klappt nicht über den Haken).
    Nutzer-Rückmeldung („man weiß nicht, ob man verbunden ist“): mit gehaltener Taste ist die Liane sofort sichtbar in der
    Hand (locker, _wartZiel) und spannt sich dann; nur angetippt (losgelassen = los, wie immer an der Liane) greift er nicht."""
    await g.load(level([ground(0, 680, 3000)], {'x': 300, 'y': 680}, {'x': 100, 'y': 680}, hooks=[{'x': 1000, 'y': 400, 'radius': 200}]))
    r = await g.ev("""(() => { menuScreen = 'pause'; let ts = 5e6; const P = p1, h = hooks[0], e = {};
      const st = () => { stepSim(ts += 1000/54); for(const k in KEYS) if(k.endsWith('_pressed')) KEYS[k] = false; };
      const setz = () => { P.x = h.x + 40; P.y = h.y - 90 + P.h*0.6; P.vx = 1; P.vy = -2; P.grounded = false; P.hookAttached = false; P.lianeSperre = 0; P._gegriffenA = null; P._hakenWarten = false; };
      setz(); KEYS.KeyG = true; KEYS.KeyG_pressed = true; st(); st();
      e.sofort = P.hookAttached; e.gleichInDerHand = P._wartZiel === h; let n = 0;
      while(!P.hookAttached && n < 80){ st(); n++; }
      e.spaeter = P.hookAttached; e.handUeber = Math.round(h.y - (P.y - P.h*0.6));
      e.winkel = Math.round(Math.abs(Math.atan2(P.x - h.x, P.y - P.h*0.6 - h.y))*180/Math.PI);
      KEYS.KeyG = false; st();
      setz(); KEYS.KeyG = true; KEYS.KeyG_pressed = true; st(); KEYS.KeyG = false;   // nur angetippt
      for(let i = 0; i < 40; i++) st(); e.ohneHalten = P.hookAttached;
      menuScreen = null; return e; })()""")
    assert not r['sofort'] and r['spaeter'] and r['winkel'] <= await g.ev('LIANE_GRIFF_WINKEL') + 1, f'von oben gegriffen: {r}'
    assert r['gleichInDerHand'] and not r['ohneHalten'], f'Liane nicht gleich in der Hand bzw. greift ohne Halten: {r}'

@test
async def liane_g_spammen(g):
    """Nutzer-Video „G spammen“: wer die Haken-Taste hektisch drückt, greift denselben Haken erst nach LIANE_SPERRE Schritten
    wieder und bekommt beim Loslassen keinen Schub, solange er kürzer als LIANE_BOOST_HALTEN Schritte am Seil hing – der Affe
    hüpft nicht mehr wild um den Haken. Ein anderer Haken lässt sich sofort greifen (Haken-Kette)."""
    await g.load(level([ground(0, 680, 4000)], {'x': 880, 'y': 680}, {'x': 600, 'y': 680},
                       hooks=[{'x': 1000, 'y': 200, 'radius': 200}, {'x': 1700, 'y': 200, 'radius': 200}]))
    r = await g.ev("""(() => { menuScreen = 'pause'; let ts = 5e6; const h = hooks[0], P = p1;
      const st = () => { stepSim(ts += 1000/54); for(const k in KEYS) if(k.endsWith('_pressed')) KEYS[k] = false; };
      const hin = (x) => { P.x = x; P.y = 200 + 80 + P.h*0.6; P.vx = 6; P.vy = 0; P.grounded = false; };
      const greif = () => { KEYS.KeyG = true; KEYS.KeyG_pressed = true; st(); return P.hookAttached; };
      const e = {};
      hin(h.x - 40); P.hookAttached = false; e.erst = greif(); for(let i = 0; i < 4; i++) st();
      KEYS.KeyG = false; st(); e.schub = P.lianeSchub || 0;             // nach 5 Schritten wieder los: kein Schub
      hin(h.x - 40); e.gleich = greif(); KEYS.KeyG = false; st();        // sofort wieder derselbe Haken: gesperrt
      for(let i = 0; i < LIANE_SPERRE; i++) st();
      hin(h.x - 40); e.spaeter = greif(); KEYS.KeyG = false; st();        // nach der Sperre wieder greifbar
      hin(1700 - 40); e.anderer = greif() && P.anchor === hooks[1];      // anderer Haken sofort
      KEYS.KeyG = false; menuScreen = null; return e; })()""")
    assert r['erst'] and r['schub'] == 0, f'kurz gehalten: kein Schub erwartet {r}'
    assert not r['gleich'] and r['spaeter'], f'Sperre für denselben Haken: {r}'
    assert r['anderer'], f'anderer Haken nicht sofort greifbar: {r}'

@test
async def liane2_natuerliches_pendel(g):
    """Liane 2 (Nutzerwunsch „Schwingen fühlt sich wie ein Bug an“, js/32 lianeSchritt): nah gegriffen rutscht der Affe weich
    bis an den Rand der Reichweite (Liane gibt sofort nach, er fällt hinein) – nie ruckartig; mit Pumpen höchstens knapp über waagerecht (kein Überschlag) und ohne Ruck; von
    oben ins Seil gefallen federt es weich nach (Ruck unter 10 px/Schritt statt ~17 – mit voller Seillänge fällt er tiefer hinein) und das Seil bleibt danach gleich lang;
    beim Loslassen mit Schwung gibt es einen spürbaren Schub nach vorn."""
    await g.load(level([ground(0, 680, 4000)], {'x': 880, 'y': 680}, {'x': 600, 'y': 680}, hooks=[{'x': 1000, 'y': 260, 'radius': 200}]))
    r = await g.ev("""(() => { menuScreen = 'pause'; let ts = 5e6; const h = hooks[0], P = p1;
      const st = () => { stepSim(ts += 1000/54); for(const k in KEYS) if(k.endsWith('_pressed')) KEYS[k] = false; };
      const setz = (x, y, vx, vy) => { P.x = x; P.y = y + P.h*0.6; P.vx = vx; P.vy = vy; P.grounded = false; P._px = P.x; P._py = P.y; P.hookAttached = false; P._lianeA = null;
        KEYS.KeyG = true; KEYS.KeyG_pressed = true; };
      const e = {};
      // 1) nah gegriffen (40 px unter dem Haken): Liane gibt bis zur Reichweite nach
      setz(h.x, h.y + 40, 0, 0); const L = []; for(let i = 0; i < 40; i++){ st(); L.push(Math.round(Math.hypot(P.x - h.x, P.y - P.h*0.6 - h.y))); }
      e.nah = {att: P.hookAttached, laengen: L.filter((_, i) => i % 5 === 0), ende: P.ropeLen, min: hookRange(h)};
      // 2) schwingen mit Pumpen 8 s: max Winkel
      setz(h.x - 120, h.y + 120, 0, 0); let maxA = 0, sprung = 0, letzt = null;
      for(let i = 0; i < 430; i++){ KEYS.KeyD = P.vx >= 0; KEYS.KeyA = P.vx < 0; st();
        const a = Math.abs(Math.atan2(P.x - h.x, P.y - P.h*0.6 - h.y))*180/Math.PI; maxA = Math.max(maxA, a);
        const v = [P.vx, P.vy]; if(letzt && i > 40) sprung = Math.max(sprung, Math.hypot(v[0]-letzt[0], v[1]-letzt[1])); letzt = v; }   // erst nach dem Hineinfallen (Liane gibt bis zur Reichweite nach)
      KEYS.KeyD = KEYS.KeyA = false;
      e.pumpen = {maxWinkel: Math.round(maxA), maxRuck: +sprung.toFixed(2), len: Math.round(P.ropeLen), att: P.hookAttached};
      // 3) von oben gegriffen: 150 px über dem Haken fallen lassen
      setz(h.x + 60, h.y - 150, 0, 6); let ruck = 0; letzt = null; const lens = [];
      for(let i = 0; i < 90; i++){ st(); const v = [P.vx, P.vy]; if(letzt) ruck = Math.max(ruck, Math.hypot(v[0]-letzt[0], v[1]-letzt[1])); letzt = v; if(i % 6 === 0) lens.push(Math.round(Math.hypot(P.x - h.x, P.y - P.h*0.6 - h.y))); }
      e.vonOben = {att: P.hookAttached, maxRuck: +ruck.toFixed(2), abstand: lens};
      // 4) Loslassen unten mit Schwung: Schub
      setz(h.x - 150, h.y + 100, 0, 0); for(let i = 0; i < 400 && !(Math.abs(P.x - h.x) < 10 && P.vx > 3); i++){ KEYS.KeyD = P.vx >= 0; KEYS.KeyA = P.vx < 0; st(); }
      KEYS.KeyD = KEYS.KeyA = false; const vor = [P.vx, P.vy]; KEYS.KeyG = false; st(); e.los = {vor: vor.map(v => +v.toFixed(2)), nach: [+P.vx.toFixed(2), +P.vy.toFixed(2)], schub: P.lianeSchub, att: P.hookAttached};
      let x0 = P.x; for(let i = 0; i < 200 && !P.grounded; i++) st(); e.los.weite = Math.round(P.x - x0);
      menuScreen = null; KEYS.KeyG = false; return e; })()""")
    n = r['nah']
    if await g.ev("LIANE_VOLLE_LAENGE"):
        assert n['att'] and abs(n['ende'] - n['min']) < 1 and abs(n['laengen'][-1] - n['min']) <= 5, f'nah gegriffen: {n}'
        assert max(n['laengen']) <= n['min'] + 30, f'nah gegriffen: federt zu weit nach {n}'
    else:   # Nutzer-Rückmeldung: bleibt so lang wie beim Greifen (kein Hineinfallen in die volle Länge)
        assert n['att'] and abs(n['ende'] - 40) <= 2 and max(n['laengen']) <= 45, f'nah gegriffen: {n}'
    p = r['pumpen']
    assert p['att'] and p['maxWinkel'] <= 100 and p['maxRuck'] < 3, f'Pumpen: Überschlag oder Ruck {p}'
    o = r['vonOben']
    assert o['att'] and o['maxRuck'] < 10 and max(o['abstand'][-5:]) - min(o['abstand'][-5:]) <= 2, f'von oben gegriffen: {o}'
    l = r['los']
    assert not l['att'] and l['schub'] > 0.9 and l['nach'][0] > l['vor'][0] + 2 and l['weite'] > 250, f'Loslassen: {l}'

@test
async def liane_halten_loslassen_schub(g):
    """Liane (Nutzerwunsch): Haken-Taste GEDRÜCKT HALTEN = am Seil bleiben; Taste loslassen = abspringen ohne Leertaste.
    Mit Schwung gibt es einen Schub in Schwungrichtung (+ kleiner Hub; seit Nutzerwunsch etwas stärker), aus dem Stand keinen."""
    await g.load(level([ground(0, 680, 4000)], {'x': 880, 'y': 680}, {'x': 840, 'y': 680}, hooks=[{'x': 1000, 'y': 300, 'radius': 260}]))
    r = await g.ev("""(() => { menuScreen = 'pause'; let ts = 5e6;
      const st = () => { stepSim(ts += 1000/54); for(const k in KEYS) if(k.endsWith('_pressed')) KEYS[k] = false; };
      const h = hooks[0], setz = vx => { p1.x = h.x; p1.y = h.y + 180 + p1.h*0.6; p1.vx = vx; p1.vy = 0; p1.grounded = false;
        p1.hookAttached = true; p1.ropeWasAirborne = true; p1.anchor = h; p1.ropeLen = 180; p1.ropeMax = 220; p1.lianeSperre = 0; p1._gegriffenA = h; p1._lianeHalten = 99; };   // umgesetzt: keine G-Sperre, „lange genug am Seil“
      const o = lianeLoslassen; let m = null;
      lianeLoslassen = P => { const a = [P.vx, P.vy]; o(P); m = {a, b: [P.vx, P.vy], k: P.lianeSchub}; };
      const e = {};
      try {
        setz(0); KEYS.KeyG = true; for(let i = 0; i < 60; i++) st(); e.haelt = p1.hookAttached;
        setz(0); st(); m = null; KEYS.KeyG = false; st(); e.still = {los: !p1.hookAttached, m};
        setz(8); KEYS.KeyG = true; st(); m = null; KEYS.KeyG = false; st(); e.schwung = {los: !p1.hookAttached, m, fling: p1.ropeFling};
        setz(-8); KEYS.KeyG = true; st(); m = null; KEYS.KeyG = false; st(); e.links = {m};
      } finally { lianeLoslassen = o; KEYS.KeyG = false; menuScreen = null; }
      return e; })()""")
    assert r['haelt'], f'Seil bleibt bei gehaltener Taste nicht dran: {r}'
    s = r['still']
    assert s['los'] and s['m'] and s['m']['k'] == 0 and s['m']['a'] == s['m']['b'], f'aus dem Stand: kein Schub erwartet: {s}'
    w = r['schwung']; m = w['m']
    assert w['los'] and m and w['fling'], f'Loslassen der Taste löst das Seil nicht: {w}'
    import math
    va, vb = math.hypot(*m['a']), math.hypot(*m['b'])
    assert m['k'] > 0.9 and 1.6 < vb - va < 3.5, f'Schub zu stark/schwach: {m}'   # LIANE_BOOST 2,4 (vorher 1,6)
    assert m['b'][0] > m['a'][0] > 0 and m['b'][1] < m['a'][1], f'Schub nicht in Schwungrichtung (+ leicht hoch): {m}'
    l = r['links']['m']
    assert l and l['b'][0] < l['a'][0] < 0, f'nach links: Schub nicht nach links: {l}'

@test
async def seil_absprung_wie_schwung(g):
    """Abspringen vom Seil: Abfluggeschwindigkeit = Schwunggeschwindigkeit (kein künstlicher Schub), Schwung bleibt erhalten."""
    for vx0 in (0, 6):
        await g.load(level([ground(0, 680, 4000)], {'x': 880, 'y': 680}, {'x': 840, 'y': 680}, hooks=[{'x': 1000, 'y': 300, 'radius': 260}]))
        await g.ev(f"""(()=>{{ const h=hooks[0]; p1.x=h.x; p1.y=h.y+180+p1.h*0.6; p1.vx={vx0}; p1.vy=0; p1.grounded=false;
          p1.hookAttached=true; p1.ropeWasAirborne=true; p1.anchor=h; p1.ropeLen=180; p1.ropeMax=220; }})()""")
        await g.ev("""window.__rv=null; window.__rv10=null; window.__rn=0; if(!window.__or){ window.__or=stepSim; stepSim=function(ts){ const was=p1.hookAttached; __or(ts);
          if(was && !p1.hookAttached && window.__rv===null){ window.__rv=p1.vx; window.__rn=0; }
          else if(window.__rv!==null && ++window.__rn===10) window.__rv10=p1.vx; }; }""")
        if vx0 == 0: await g.p.keyboard.down('KeyD')
        # Zustand setzen und sofort springen (im selben Aufruf) – sonst schwingt die Figur auf langsamen Rechnern
        # vorher schon ein paar Schritte, und der Abflug-Schwung ist nicht mehr der gesetzte
        await g.ev(f"""(()=>{{ const h=hooks[0]; p1.x=h.x; p1.y=h.y+180+p1.h*0.6; p1.vx={vx0}; p1.vy=0; p1.grounded=false;
          p1.hookAttached=true; p1.ropeWasAirborne=true; p1.anchor=h; p1.ropeLen=180; p1.ropeMax=220; p1._px=p1.x; p1._py=p1.y;
          KEYS.Space = true; KEYS.Space_pressed = true; KEYS.KeyG = true; }})()""")
        await g.p.wait_for_timeout(120); await g.ev("KEYS.Space = false; KEYS.KeyG = false"); await g.p.wait_for_timeout(200)
        rv, vx = await g.ev("window.__rv"), await g.ev("window.__rv10")   # vx 10 Schritte nach dem Loslassen
        if vx0 == 0:
            await g.p.keyboard.up('KeyD')
            assert rv is not None and abs(rv) < 2, f'künstlicher Schub beim Abspringen aus dem Stand: {rv}'
            assert vx <= 7.3, f'zu schnell ohne Schwung: {vx}'
        else:
            assert rv is not None and abs(rv - 6) < 1.2, f'Abflug passt nicht zum Schwung (6): {rv}'
            assert vx > rv*0.88, f'Schwung nach dem Loslassen weg: {rv} -> {vx}'

# ---------------------------------------------------------------- Runner

@test
async def level_themen(g):
    """Jedes Level hat sein eigenes Aussehen (Thema): Level 1 Dschungel, 2 Abendrot, 3 Ruinen; alle 6 Themen
    zeichnen fehlerfrei; Nacht/Höhle sind dunkel mit Licht um die Figuren; der Editor speichert das Thema."""
    # Level 1: kein altes Thema mehr – Nacht über Welt + Tageszeit (Nutzerwunsch, Test level1_bei_nacht)
    erwartet = {   # (Dschungel: die alten Teile sind in den Abschnitten aufgegangen – Welt + Tageszeit statt Thema)
                'ruinen/01-ruinen.json': 'ruinen', 'ruinen/02-mondnacht.json': 'nacht', 'hoehle/01-kristallhoehle.json': 'hoehle', 'vulkan/03-feuerberg.json': 'vulkan'}
    for datei, th in erwartet.items():
        d = ABS.lies(datei)
        assert d.get('theme') == th, f'{datei}: Thema {d.get("theme")} statt {th}'
    assert await g.ev("THEME_ORDER.join(',')") == 'dschungel,abend,ruinen,nacht,hoehle,vulkan'
    await g.load(level([ground(0, 680, 3000), ground(400, 560, 200, 40, 'wall'), ground(700, 680, 120, 40, 'crumble')],
                       {'x': 300, 'y': 680}, {'x': 260, 'y': 680}, theme='nacht',
                       coins=[{'x': 500, 'y': 600, 'color': 'blue'}], switches=[{'x': 900, 'y': 660, 'link': 1}],
                       hooks=[{'x': 1000, 'y': 400, 'radius': 160}], checkpoints=[{'x': 1100, 'y': 680}]))
    await g.p.wait_for_timeout(300)   # dunkles Thema mit Münzen, Hebel, Haken: Zeichnen ohne Fehler
    assert await g.ev('themeName') == 'nacht', 'Thema aus der Level-Datei nicht übernommen'
    farben = set()
    for th in ('dschungel', 'abend', 'ruinen', 'nacht', 'hoehle', 'vulkan'):
        await g.ev(f"setTheme('{th}')"); await g.p.wait_for_timeout(350)
        # Farbe des Himmels oben links unterscheidet sich je Thema (Dschungel-Paket: Dschungel-Morgen und das alte Thema
        # „abend“ (Baumkronen, Dschungel-Welt) haben beide den neuen Dschungel-Hintergrund mit seinem grünen Himmel)
        farben.add(await g.ev("Array.from((BG_STIL ? DJ.sky : BG_SKY).getContext('2d').getImageData(5, 5, 1, 1).data).slice(0,3).join(',')"))
        assert await g.ev('THEME.ground.grass'), 'keine Bodenfarbe'
    assert len(farben) == 5, f'Themen sehen gleich aus: {farben}'
    # dunkles Thema: Bild um die Figur heller als weit weg
    await g.ev("setTheme('hoehle')"); await g.p.wait_for_timeout(400)
    hell = await g.ev("""(()=>{ const sx=Math.round((p1.x-camX)*zoom), sy=Math.round((p1.y-p1.h*0.5)*zoom+H*(1-zoom));
        const k = darkCanvas.width/W;   // Dunkel-Schicht in halber Auflösung (Design-Politur)
        const a = darkCtx.getImageData(Math.round(sx*k), Math.round(sy*k), 1, 1).data[3], b = darkCtx.getImageData(Math.round(Math.min(W-2, sx+600)*k), Math.round(60*k), 1, 1).data[3]; return [a, b]; })()""")
    assert hell[0] < hell[1], f'kein Licht um die Figur: {hell}'
    # ohne Thema: Dschungel
    await g.load(level([ground(0, 680, 3000)], {'x': 300, 'y': 680}, {'x': 260, 'y': 680}))
    assert await g.ev('themeName') == 'dschungel'
    # Editor: Thema wählen -> gespeichert, exportiert und im Spiel-Format
    srv = webserver()
    try:
        p = g.p
        await p.goto(srv.url + 'editor/index.html'); await p.wait_for_timeout(300)
        # seit Ausbau 2: Thema = „Look-Override“ im Fenster Level-Info
        await p.click('#metaBtn'); await p.select_option('#metaLook', 'vulkan'); await p.click('#metaClose'); await p.wait_for_timeout(100)
        roh = await p.evaluate("JSON.parse(localStorage.getItem('monchichi_level_editor_v2')).theme")
        assert roh == 'vulkan', f'Editor speichert das Thema nicht: {roh}'
        await p.reload(); await p.wait_for_timeout(300)
        assert await p.eval_on_selector('#metaLook', 'e => e.value') == 'vulkan', 'Thema nach Neuladen weg'
        await p.click('#exportBtn'); await p.wait_for_timeout(200)
        exp = json.loads(await p.eval_on_selector('#exportText', 'e => e.value'))
        assert exp.get('theme') == 'vulkan', 'Export ohne Thema'
    finally:
        srv.shutdown()

@test
async def aufwind_saeule(g):
    """Aufwind-Aussehen: übereinander liegende Kästchen-Reihen (so speichert der Editor) werden zum Zeichnen zu EINER
    Säule zusammengefasst – keine einzelnen Blöcke und keine Linien an den Nähten mehr; getrennte Bereiche bleiben getrennt. Zeichnen läuft fehlerfrei."""
    reihen = [{'x': 400, 'y': y0, 'w': 80, 'h': 40} for y0 in range(200, 680, 40)]
    lv = level([ground(0, 680, 3000)], {'x': 100, 'y': 680}, {'x': 160, 'y': 680},
               winds=reihen + [{'x': 800, 'y': 400, 'w': 120, 'h': 280}, {'x': 480, 'y': 160, 'w': 40, 'h': 40}])
    await g.load(lv); await g.p.wait_for_timeout(200)
    s = await g.ev("windSaeulen().map(s => [s.x, s.y, s.w, s.h, s.teile.length]).sort((a, b) => a[0] - b[0] || a[1] - b[1])")
    # teile = 1: die 12 Reihen sind zu EINEM Rechteck verbunden (sonst feine Linien an den Kästchen-Nähten)
    assert s == [[400, 200, 80, 480, 1], [480, 160, 40, 40, 1], [800, 400, 120, 280, 1]], f'Säulen falsch: {s}'
    fehler = await g.ev("(() => { try { draw(); return null; } catch(e) { return String(e); } })()")
    assert fehler is None, fehler

@test
async def neue_elemente(g):
    """Druckplatte (Tür offen nur solange jemand draufsteht), Aufwind (trägt das Schweinchen mit Schirm hoch,
    den Affen nicht), Scheinwand (durchlaufbar, sieht aus wie Wand), Sprungpilz (schleudert ~6 Kästchen hoch, nur beim Draufspringen)."""
    lv = level([ground(0, 680, 3000)], {'x': 140, 'y': 680}, {'x': 100, 'y': 680},
               plates=[{'x': 300, 'y': 660, 'link': 3}], doors=[{'x': 620, 'y': 660, 'link': 3}, {'x': 620, 'y': 620, 'link': 3}])
    await g.load(lv)
    tuer = "solids.filter(s=>s.type==='door').every(d=>d.gone)"
    assert not await g.ev(tuer), 'Tür ist am Anfang offen'
    # zur Platte laufen, bis der Affe dort ist (feste Zeiten passen nicht auf jeden Rechner)
    await g.p.keyboard.down('KeyD')
    try: await g.p.wait_for_function("p1.x >= 272", timeout=6000)
    except Exception: pass
    await g.p.keyboard.up('KeyD'); await g.steps(14)
    x = await g.ev('p1.x')
    assert abs(x - 300) < 40, f'Affe nicht auf der Platte: {x}'
    if abs(x - 300) >= 16: await g.ev('p1.x = 300; p1.vx = 0')
    await g.p.wait_for_timeout(200)
    assert await g.ev(tuer), 'Druckplatte öffnet die Tür nicht'
    assert await g.ev('plates[0].down'), 'Platte nicht gedrückt'
    await g.ev('p1.x = 460'); await g.p.wait_for_timeout(250)
    assert not await g.ev(tuer), 'Tür bleibt offen, obwohl niemand mehr auf der Platte steht'

    # Aufwind: Schweinchen mit Schirm steigt, Affe nicht
    lv = level([ground(0, 680, 3000)], {'x': 700, 'y': 680}, {'x': 300, 'y': 680},
               winds=[{'x': 240, 'y': 120, 'w': 120, 'h': 560}])
    await g.load(lv); await g.p.wait_for_timeout(200)
    await g.p.keyboard.down('Numpad0'); await g.p.wait_for_timeout(60); await g.p.keyboard.down('Numpad1')
    await g.p.wait_for_timeout(1400)
    y = await g.ev('p2.y')
    await g.p.keyboard.up('Numpad0'); await g.p.keyboard.up('Numpad1')
    assert y < 400, f'Aufwind trägt das Schweinchen nicht: y={y:.0f}'
    await g.ev('p1.x = 300; p1.y = 680; p2.x = 700'); await g.p.wait_for_timeout(200)
    await g.hold(('Space',), 200); await g.p.wait_for_timeout(900)
    assert await g.ev('p1.y') > 660, 'Aufwind trägt auch den Affen'

    # Scheinwand: Affe läuft hindurch
    lv = level([ground(0, 680, 3000), {'x': 400, 'y': 440, 'w': 120, 'h': 240, 'type': 'fake'}],
               {'x': 300, 'y': 680}, {'x': 100, 'y': 680})
    await g.load(lv)
    assert await g.ev('fakeWalls.length') == 1 and await g.ev("!solids.some(s=>s.type==='fake')"), 'Scheinwand nicht geladen'
    await g.hold(('KeyD',), 900)
    assert await g.ev('p1.x') > 540, f"Affe kommt nicht durch die Scheinwand: {await g.ev('p1.x')}"

    # Sprungpilz: drüberlaufen -> nichts passiert; draufspringen -> hoch geschleudert
    lv = level([ground(0, 680, 3000)], {'x': 300, 'y': 680}, {'x': 100, 'y': 680}, bouncers=[{'x': 380, 'y': 680}])
    await g.load(lv)
    await g.ev("window.__minY = 999; window.__minVy = 0; if(!window.__bo){ window.__bo = 1; const o = stepSim; stepSim = function(ts){ o(ts); window.__minY = Math.min(window.__minY, p1.y); window.__minVy = Math.min(window.__minVy, p1.vy); }; }")
    await g.hold(('KeyD',), 300); await g.p.wait_for_timeout(1200)
    hoch = 680 - await g.ev('window.__minY')
    assert hoch < 5 and await g.ev('p1.x') > 400, f'Sprungpilz beim Drüberlaufen ausgelöst: {hoch:.0f} px hoch'
    await g.ev("p1.x = 380; p1.y = 520; p1.vx = 0; p1.vy = 2; p1.grounded = false; p1._px = p1.x; p1._py = p1.y; window.__minVy = 0; window.__minY = 999")
    await g.p.wait_for_timeout(1500)
    assert await g.ev('window.__minVy') <= -17, f"Sprungpilz beim Draufspringen nicht ausgelöst: {await g.ev('window.__minVy')}"
    hoch = 680 - await g.ev('window.__minY')
    assert 200 < hoch < 280, f'Sprungpilz: {hoch:.0f} px hoch (erwartet ~230)'

@test
async def sprungpilz_hutrand(g):
    """Nutzer-Rückmeldung „man springt häufig ins Leere“: der Sprungpilz federt auf der ganzen Hutbreite (PILZ_TREFFER 22 px
    + halbe Figurenbreite neben der Mitte, vorher 14) – auch wer auf dem Hutrand landet, wird hochgeschleudert; daneben nicht."""
    lv = level([ground(0, 680, 3000)], {'x': 300, 'y': 680}, {'x': 100, 'y': 680}, bouncers=[{'x': 800, 'y': 680}])
    await g.load(lv)
    assert await g.ev("PILZ_TREFFER") == 22
    await g.ev("window.__minVy = 0; if(!window.__hr){ window.__hr = 1; const o = stepSim; stepSim = function(ts){ o(ts); window.__minVy = Math.min(window.__minVy, p1.vy); }; }")
    for dx, soll in ((0, True), (33, True), (-33, True), (48, False)):
        await g.ev(f"p1.x = {800 + dx}; p1.y = 560; p1.vx = 0; p1.vy = 2; p1.grounded = false; p1._px = p1.x; p1._py = p1.y; window.__minVy = 0")
        await g.steps(60)
        hoch = await g.ev('window.__minVy') <= -17
        assert hoch == soll, f'Sprungpilz bei {dx} px neben der Mitte: {"federt" if hoch else "federt nicht"} (soll {soll})'
        await g.steps(90)

@test
async def editor_neue_werkzeuge(g):
    """Editor: Scheinwand, Aufwind, Sprungpilz und Druckplatte setzen -> Export und Spiel-Umwandlung enthalten sie."""
    srv = webserver()
