        assert exp['plates'] == [{'x': 140, 'y': 580, 'link': 4}], f"Druckplatte falsch: {exp['plates']}"
        assert exp['bouncers'] == [{'x': 500, 'y': 600}], f"Sprungpilz falsch: {exp['bouncers']}"
