@test
async def alte_levels_unveraendert(g):
    """Ausbau 1: alle Level-Dateien (ohne welt/tageszeit/wetter) laden weiter mit ihrem bisherigen Look und
    wechselndem Wetter; das Testlevel levels/test/schichten-dschungel.json lässt sich direkt öffnen, T/Z schalten durch."""
    for d in json.loads((ROOT / 'levels' / 'levels.json').read_text(encoding='utf-8')):
        if d.get('boss'): continue   # Boss-Level (Ausbau 6) sind neu, mit eigener Welt/Tageszeit
        data = ABS.lies(d['datei'])
        if data.get('welt'): continue   # neue Level (Ausbau 7) beschreiben ihr Aussehen mit welt/tageszeit/wetter
        await g.load(level_pfad(d['datei'])); await g.p.wait_for_timeout(150)
        k = await g.ev("({look: levelTheme, mode: weatherMode, wash: !!THEME.layerWash})")
        assert k == {'look': data.get('theme') or 'dschungel', 'mode': 'wechselnd', 'wash': False}, f"{d['datei']}: {k}"
    srv = webserver(); p = g.p
    try:
        await p.goto(srv.url + 'index.html?testlevel=schichten-dschungel')
        await p.wait_for_function("typeof levelLayers !== 'undefined' && levelLayers.vorschau && menuScreen === null", timeout=8000)
        seen = []
        for _ in range(4):
            await p.keyboard.press('KeyT'); await p.wait_for_timeout(120)
            seen.append(await g.ev("[levelLayers.tageszeit, !!THEME.moon]"))
        assert [x[0] for x in seen] == ['mittag', 'abend', 'nacht', 'morgen'] and seen[2][1] and not seen[3][1], seen
        modes = []
        for _ in range(3):
            await p.keyboard.press('KeyZ'); await p.wait_for_timeout(120)
            modes.append(await g.ev("weatherMode"))
        assert modes == ['trocken', 'regen', 'wechselnd'], modes
    finally:
        srv.shutdown()

@test
async def bahnen_alte_mechaniken(g):
    """Nacht-Ausbau (harte Regel): Laufen, Sprung, Kamin-Wandsprung, Haken-Schwung (+ Seil ran/geben), Segeln, Aufwind,
    Sprungpilz und Einzelwand liefern Schritt für Schritt EXAKT dieselben Bahnen wie vor dem Einbau von Dash, Durchbruch-
    Wand, Wand-Rutschen und Haftfläche. Referenz: tests/bahnen_referenz.json (vor dem Ausbau aufgezeichnet, nie anpassen)."""
    ref = json.loads((ROOT / 'tests' / 'bahnen_referenz.json').read_text(encoding='utf-8'))
    assert len(ref) >= 7, len(ref)
    srv = webserver(); p = g.p
    try:
        await p.goto(srv.url + 'index.html?testlevel=bahnen')
        await p.wait_for_function("typeof p1 !== 'undefined' && p1 && solids.length > 3 && menuScreen === null", timeout=15000)
        await p.evaluate("() => {" + (ROOT / 'tests' / 'bahnen.js').read_text(encoding='utf-8') + "}")
        erg = await p.evaluate("ref => bahnenAbspielen(ref)", ref)
        falsch = [e for e in erg if e.get('fehler', 'x') is not None]
        assert not falsch, f'Bahnen weichen ab: {falsch[:3]}'
        assert sum(e['schritte'] for e in erg) >= 2000, erg
    finally:
        srv.shutdown()

async def neue_mechaniken_messen(g, teil):
    """Nacht-Ausbau: Szenario aus tests/neue_mechaniken.js im Testlevel neue-mechaniken laufen lassen."""
    srv = webserver(); p = g.p
    try:
        await p.goto(srv.url + 'index.html?testlevel=neue-mechaniken')
        await p.wait_for_function("typeof p1 !== 'undefined' && p1 && solids.length > 3 && menuScreen === null", timeout=15000)
        await p.evaluate("() => {" + (ROOT / 'tests' / 'neue_mechaniken.js').read_text(encoding='utf-8') + "}")
        await p.evaluate("levelWelt = 'mechanik-test'")   # Dash prüfen (im Dschungel ist er aus – DASH_AUS_WELTEN; die Mechanik bleibt für andere Welten)
        return await p.evaluate(f"NM.{teil}()")
    finally:
        srv.shutdown()

@test
async def dash_richtungen_und_laden(g):
    """Nacht-Ausbau: Dash – seit Nutzerwunsch nur noch nach links/rechts (DASH_NUR_WAAGERECHT): hoch/runter/schräg
    gedrückt geht er waagerecht (ohne Richtung in Blickrichtung); Boden und Luft, beide Figuren, nur ein Luft-Dash,
    Aufladen am Boden, an der Wand und am Haken, kein Durchtunneln von Wänden."""
    r = await neue_mechaniken_messen(g, 'dash')
    for wer in 'mf':
        R = {k[1:]: v for k, v in r['richtung'].items() if k[0] == wer}
        assert R['r'][0] > 3.5 and R['l'][0] < -3.5, (wer, R)
        for d in ('ro', 'ru'): assert R[d][0] > 3.5, (wer, d, R[d])
        for d in ('lo', 'lu'): assert R[d][0] < -3.5, (wer, d, R[d])
        for d in ('o', 'u'): assert abs(R[d][0]) > 3.5, (wer, d, R[d])   # ohne links/rechts: in Blickrichtung
        assert all(abs(v[1]) < 0.5 for v in R.values()), f'Dash nicht waagerecht: {R}'
        assert all(v[2] == 0 for v in R.values()), f'Luft-Dash kostet keinen Punkt: {R}'
        assert r[wer + 'Boden'] > 3.5, (wer, r[wer + 'Boden'])
    assert not r['zweiterLuftDash'], 'zweiter Luft-Dash ging'
    assert r['ladungInLuft'], 'Dash lädt in der Luft nicht (neue Regel: immer laden)'
    assert 120 <= r['ladeSchritte'] <= 140, r['ladeSchritte']   # DASH_LADEZEIT 120 nach dem Dash (+ Dash-Dauer), auch in der Luft
    assert r['wandLaden']['vorher'] == 0 and r['wandLaden']['schritte'] < 120, r['wandLaden']
    if r['hakenLaden'] is not None:
        assert r['hakenLaden']['haken'] and r['hakenLaden']['punkte'] == 1, r['hakenLaden']
    assert r['keinTunnel'] < 90 and r['keinTunnelSchraeg'] < 90, (r['keinTunnel'], r['keinTunnelSchraeg'])

@test
async def durchbruch_wand(g):
    """Nacht-Ausbau: Durchbruch-Wand bricht nur durch einen Dash (Laufen/Springen nicht), beide Figuren; seit der Dash
    nur noch waagerecht geht (Nutzerwunsch), bricht ein Durchbruch-Boden von oben NICHT mehr; Trefferstopp; bleibt kaputt
    bis Neustart; Option „wächst nach“ wartet, solange eine Figur drin steht."""
    r = await neue_mechaniken_messen(g, 'bruch')
    assert r['laufen']['weg'] == 0 and r['laufen']['c'] < 20, r['laufen']
    assert r['dash']['weg'] >= 1 and r['dash']['c'] > 21, r['dash']
    assert r['dash']['stopp'] >= 1, f"kein Trefferstopp: {r['dash']}"
    assert r['schwein']['weg'] >= 1 and r['schwein']['c'] > 21, r['schwein']
    assert r['unten']['weg'] == 0, f'Durchbruch-Boden bricht trotz waagerechtem Dash: {r["unten"]}'
    assert r['bleibt'] >= 1 and r['nachNeustart'] == 0, r
    w = r['wachsen']
    assert w['wegNachDash'] >= 1 and w['wartet'] and w['wegMitFigur'] >= 1 and w['frei'], w
    assert w['wegOhneFigur'] == 0, w

@test
async def wand_rutschen(g):
    """Nacht-Ausbau: an einer Wand herunterfallen bremst automatisch auf WAND_RUTSCH_MAX_FALL (ohne Richtungstaste,
    beide Figuren); ein Wandsprung mitten im Rutschen ist der ganz normale Wandsprung."""
    r = await neue_mechaniken_messen(g, 'rutschen')
    gr = await g.ev("WAND_RUTSCH_MAX_FALL")
    assert r['ohneTaste']['maxVy'] <= gr + 1e-6 and r['ohneTaste']['rutschte'] > 5, r
    assert r['schwein'] <= gr + 1e-6, r
    assert r['wandsprung']['vx'] < -3 and r['wandsprung']['vy'] < -8, r['wandsprung']

@test
async def durchbruch_kein_gratis_dash(g):
    """Nach einem Durchbruch gibt es KEINEN kostenlosen Anschluss-Dash mehr (Nutzerwunsch: ein Dash, dann aufladen) – auch
    nicht im Durchbruch-Fenster; der Sprung in der Luft im Fenster bleibt. Ist der Punkt wieder geladen, geht der Dash."""
    srv = webserver()
    try:
        await g.p.goto(srv.url + 'index.html?testlevel=neue-mechaniken')
        await g.p.wait_for_function("typeof p1 !== 'undefined' && p1 && solids.length > 3 && menuScreen === null", timeout=15000)
        await g.p.evaluate("() => {" + (ROOT / 'tests' / 'neue_mechaniken.js').read_text(encoding='utf-8') + "}")
        await g.p.evaluate("levelWelt = 'mechanik-test'")   # Dash prüfen (im Dschungel aus)
        r = await g.ev("""(() => { const S = NM; menuScreen = 'pause';
          S.start(); S.stellen(p1, 16, 17); S.stellen(p2, 12, 17); S.n(10, ['right']);
          S.schritt(['right','dash']); let i = 0; while(!S.weg() && i < 30){ S.schritt(['right']); i++; }
          let k = 0; while((p1.dash || p1.dashPause > 0) && k < 40){ S.schritt(['right']); k++; }
          const fenster = p1.bruchFenster, punkte = p1.dashPunkte;
          S.schritt(['right','dash']); S.schritt(['right']); const gratis = !!p1.dash;
          S.n(DASH_LADEZEIT + 10); S.schritt(['dash']); const geladen = !!p1.dash;
          return {weg: S.weg(), fenster, punkte, gratis, geladen}; })()""")
        assert r['weg'] == 1 and r['fenster'] > 0 and r['punkte'] == 0, f'Aufbau: {r}'
        assert not r['gratis'], f'nach dem Durchbruch ging ohne Dash-Punkt noch ein Dash: {r}'
        assert r['geladen'], f'nach dem Aufladen geht der Dash wieder: {r}'
    finally:
        srv.shutdown()

# ---- 3D-Figuren (js/33-figuren-3d.js): zeichnen in einer kleinen WebGL-Leinwand und ersetzen fussFigurZeichnen ----
F3D_ZEICHNEN = """(o) => {   // die Figur(en) o.n Bilder lang zeichnen; jedes Bild zählt als 50 ms (die 3D-Figur glättet über die Zeit) –
  // ohne Pausen, damit die Spielschleife nicht dazwischen zeichnet, und gleich auf schnellen und langsamen Rechnern
  menuScreen = 'pause';
  const merk = [];
  for(let i = 0; i < o.n; i++){
    if(o.vorher) Function(o.vorher)();
    for(const P of o.wer === 'beide' ? [p2, p1] : [o.wer === 'f' ? p2 : p1]){ if(P._f3) P._f3.t = performance.now() - 50; ctx.save(); drawCharacter(P, camX); ctx.restore(); }
    if(o.merk) merk.push(Function('return (' + o.merk + ')')());
  }
  return merk;
}"""

async def f3d_bereit(g):
    """Level laden und prüfen, dass die 3D-Figuren wirklich zeichnen (WebGL2 da, 3D an). Der Testrechner hat nur
    Software-Grafik – dort bleiben sonst die bisherigen Figuren; hier wird 3D erzwungen (langsam, aber für ein paar Bilder ok)."""
    await g.p.add_init_script("window.figuren3dErzwingen = true")
    g._srv = webserver(); await g.p.goto(g._srv.url + 'index.html'); await g.p.wait_for_timeout(400)   # Webserver: Leinwand lesbar
    await g.load(level([ground(0, 680, 2400)], {'x': 600, 'y': 680}, {'x': 520, 'y': 680}, welt='ruinen'))
    await g.steps(10)
    await g.p.evaluate(F3D_ZEICHNEN, {'n': 2, 'wer': 'beide'})
    assert await g.ev("!!(p1._f3 && p2._f3)"), '3D-Figuren zeichnen nicht (WebGL2 fehlt oder 3D aus)'

@test
async def figuren3d_seil_waagerecht_nicht_im_boden(g):
    """Nutzer-Screenshot „ich schwinge immer noch in Boden/Wand“: hängt der Affe waagerecht am Seil knapp über einer
    Bodenkante, wird der 3D-Körper (dick, mit Fell) nicht mehr gedreht in die Erde gezeichnet – die Prüfung am Seil schaut
    jetzt auch quer zum Körper (SEIL_KOERPER_BREITE, js/33) und richtet ihn auf."""
    await f3d_bereit(g)
    await g.load(level([ground(0, 680, 2400), ground(1000, 560, 400, 120)], {'x': 600, 'y': 680}, {'x': 520, 'y': 680},
                       hooks=[{'x': 840, 'y': 536, 'radius': 220}], welt='ruinen'))
    await g.steps(5)
    r = await g.p.evaluate(F3D_ZEICHNEN, {'n': 12, 'wer': 'm', 'vorher': """p1.x = 1016; p1.y = 555; p1.vx = 0; p1.vy = 0; p1.grounded = false;
        p1.hookAttached = true; p1.anchor = hooks[0]; p1.ropeLen = 176; p1._seilTest = 1""", 'merk': "p1._f3 ? p1._f3.rs : null"})
    await g.ev("p1.hookAttached = false; p1.anchor = null; menuScreen = null")
    assert r[-1] is not None and abs(r[-1]) < 0.45, f'Körper liegt gedreht im Boden: Drehung {r[-1]:.2f} rad'

@test
async def brillen_steg_und_buegel(g):
    """Alle Brillen (Umkleide): vorn ein Steg über der Nase und an beiden Seiten ein Bügel – Steg/Bügel werden NACH den Gläsern
    gezeichnet und setzen am Glasrand an (vorher von großen Gläsern wie Herz/Stern verdeckt, Cyber ohne Bügel)."""
    r = await g.ev("""(() => { const cv = document.createElement('canvas'); cv.width = 300; cv.height = 200; const c = cv.getContext('2d');
      // Abstände wie an der 3D-Figur (Glas-Halbbreite ≈ 0,33 × Augenabstand)
      const w = 33, h = 37, L = [100, 100], R = [200, 100], out = {};
      const RAHMEN = {classic:'#111111', round:'#c9a24a', aviator:'#d8b660', shutter:'#ffffff', heart:'#d6336c', '3d':'#f3f3f3', star:'#f5b800', bling:'#ffd23f'};
      const hex = s => [1, 3, 5].map(i => parseInt(s.slice(i, i + 2), 16));
      const da = (x, y) => { const d = c.getImageData(Math.round(x) - 2, Math.round(y) - 2, 5, 5).data; for(let i = 3; i < d.length; i += 4) if(d[i] > 40) return true; return false; };
      const farbe = (x, y, col) => { const d = c.getImageData(Math.round(x) - 2, Math.round(y) - 2, 5, 5).data, z = hex(col);   // Rahmenfarbe obenauf?
        for(let i = 0; i < d.length; i += 4) if(d[i+3] > 200 && Math.abs(d[i] - z[0]) + Math.abs(d[i+1] - z[1]) + Math.abs(d[i+2] - z[2]) < 60) return true; return false; };
      for(const it of COSMETICS.filter(i => i.slot === 'glasses')){
        const k = it.fx.kind; c.clearRect(0, 0, 300, 200); drawGlasses(c, k, L, R, w, h);
        out[it.id] = {steg: k === 'cyber' ? da(150, 100) : farbe(150, 100 - h*0.425, RAHMEN[k]),
                      links: da(L[0] - 1.85*w, L[1] - h*0.47), rechts: da(R[0] + 1.85*w, R[1] - h*0.47)};
      }
      return out; })()""")
    fehlt = {k: v for k, v in r.items() if not all(v.values())}
    assert not fehlt, f'Brillen ohne Steg/Bügel: {fehlt}'
    assert len(r) == 9, f'nicht alle Brillen geprüft: {list(r)}'

@test
async def figuren3d_siegestanz(g):
    """3D-Figuren: Siegestanz zu zweit – stehen beide nahe beieinander, erkennen sie den Partner (tz.near), haken die
    inneren Arme ein (Einhak-Anteil ti wächst) und schauen zur Kamera; nur Zeichnen, ohne Fehler."""
