# Dschungel-Neu (js/34-koop-aktionen.js): Schritte direkt rechnen (Spiel angehalten), Tasten wie ein Spieler
KOOP_SCHRITTE = """menuScreen = 'pause'; deathState = null; let ts = 5e6; for(const k in KEYS) KEYS[k] = false;
  const st = () => { stepSim(ts += 1000/54); for(const k in KEYS) if(k.endsWith('_pressed')) KEYS[k] = false; };
  const stell = (P, x, y) => { P.x = x; P.y = y; P.vx = P.vy = 0; P.grounded = false; };"""

async def koop_testlevel(g):
    srv = webserver()
    await g.p.goto(srv.url + 'index.html?testlevel=koop-aktionen')
    await g.p.wait_for_function("typeof p1 !== 'undefined' && p1 && solids.length >= 4 && windraeder.length === 2 && blattFloesse.length === 1 && menuScreen === null", timeout=10000)
    return srv

@test
async def koop_trampolin_schub(g):
    """Nutzerwunsch: drückt das Schweinchen (Schirm-Trampolin gehalten) im richtigen Moment Springen – kurz vor oder kurz nach dem
    Aufprall des Affen (TRAMPOLIN_SCHUB_FENSTER) –, bekommt der Affe einen Extra-Schub (TRAMPOLIN_V_SCHUB, deutlich höher).
    Zu früh gedrückt oder gar nicht: normale Höhe. Höchstens ein Schub je Aufprall; eigener Ton."""
    srv = await koop_testlevel(g)
    try:
        r = await g.ev("""(() => { """ + KOOP_SCHRITTE + """ const e = {};
          const flug = (wann) => {   // wann: Schritte relativ zum Aufprall (null = nie drücken)
            for(const k in KEYS) KEYS[k] = false; stell(p2, 300, 720); stell(p1, 160, 720); for(let i = 0; i < 6; i++) st();
            KEYS[p2.keys.trampolin] = true; for(let i = 0; i < 4; i++) st();
            stell(p1, 300, 520); let top = 1e9, auf = null, gedrueckt = false;
            for(let i = 0; i < 120; i++){
              const vorher = p1.vy;
              if(wann !== null && auf === null && wann < 0 && p1.vy > 0 && p1.y > 646 + wann*Math.max(1, p1.vy) && !gedrueckt){ KEYS[p2.keys.jump + '_pressed'] = true; gedrueckt = true; }
              if(wann !== null && auf !== null && wann >= 0 && i - auf === wann && !gedrueckt){ KEYS[p2.keys.jump + '_pressed'] = true; gedrueckt = true; }
              st(); if(auf === null && vorher > 0 && p1.vy < 0) auf = i;
              top = Math.min(top, p1.y);
            }
            return Math.round((720 - top)/4)/10;
          };
          e.ohne = flug(null); e.kurzVorher = flug(-3); e.kurzNachher = flug(3); e.zuFrueh = flug(-40); e.zuSpaet = flug(20);
          e.ton = SFX_LOG.includes('trampolinSchub');
          for(const k in KEYS) KEYS[k] = false; menuScreen = null; return e; })()""")
        assert r['kurzVorher'] > r['ohne'] + 1.2 and r['kurzNachher'] > r['ohne'] + 1.0, f'kein Extra-Schub im richtigen Moment: {r}'
        assert abs(r['zuFrueh'] - r['ohne']) < 0.3 and abs(r['zuSpaet'] - r['ohne']) < 0.3, f'Schub auch zur falschen Zeit: {r}'
        assert r['ton'], r
    finally:
        srv.shutdown()

@test
async def koop_schirm_trampolin(g):
    """Dschungel-Neu: Schweinchen hält die Spezial-Taste (Num 4) -> spannt den offenen Schirm über sich, steht still (kein
    Laufen, kein Springen). Fällt der Affe von oben auf den Schirm (TRAMPOLIN_HOEHE über ihren Füßen), federt er hoch – höchster
    Punkt wie früher vom Sprungpilz (≈ 6 Reihen über dem Boden) – und kommt so auf den 6 Reihen hohen Sims (Testlevel
    koop-aktionen). Drunterlaufen tut nichts; ohne Schirm gibt es keinen Schwung; Taste los = Schirm zu, läuft normal."""
    srv = await koop_testlevel(g)
    try:
        r = await g.ev("""(() => { """ + KOOP_SCHRITTE + """ const e = {};
          try {
            stell(p2, 600, 720); stell(p1, 300, 720); for(let i = 0; i < 6; i++) st();
            KEYS[p2.keys.trampolin] = true; for(let i = 0; i < 4; i++) st(); e.schirm = p2.trampolin;
            KEYS[p2.keys.left] = true; KEYS[p2.keys.jump] = true; KEYS[p2.keys.jump + '_pressed'] = true; for(let i = 0; i < 10; i++) st();
            e.still = Math.abs(p2.x - 600) < 1 && p2.grounded; KEYS[p2.keys.left] = false; KEYS[p2.keys.jump] = false;
            // drunterlaufen: kein Schwung
            stell(p1, 500, 720); for(let i = 0; i < 4; i++) st(); KEYS[p1.keys.right] = true; let minY = 1e9;
            for(let i = 0; i < 30; i++){ st(); minY = Math.min(minY, p1.y); } KEYS[p1.keys.right] = false; e.drunter = 720 - minY;
            // von oben (neben dem Sims 640–880, Oberkante y 480): hoch und hinüber
            stell(p1, 600, 560); let boing = 0, top = 1e9;
            for(let i = 0; i < 90; i++){ KEYS[p1.keys.right] = p1.vy > -6 && p1.y < 560 && p1.x < 720; st(); top = Math.min(top, p1.y); if(p1.vy <= TRAMPOLIN_V + 0.01) boing++; }
            KEYS[p1.keys.right] = false; for(let i = 0; i < 60; i++) st();
            e.boing = boing; e.hoch = (720 - top)/40; e.aufSims = p1.grounded && Math.abs(p1.y - 480) < 1 && p1.x > 640;
            e.log = SFX_LOG.slice(-40);
            KEYS[p2.keys.trampolin] = false; for(let i = 0; i < 4; i++) st(); e.zu = !p2.trampolin;
            stell(p1, 600, 560); let b2 = 0; for(let i = 0; i < 40; i++){ st(); if(p1.vy < -10) b2++; } e.ohne = b2;
          } finally { for(const k in KEYS) KEYS[k] = false; menuScreen = null; }
          return e; })()""")
        assert r['schirm'] and r['still'], f'Schweinchen spannt den Schirm nicht / bewegt sich dabei: {r}'
        assert r['drunter'] < 2, f'Drunterlaufen darf nicht hochschleudern: {r}'
        assert r['boing'] >= 1 and 6.2 < r['hoch'] < 7.2 and r['aufSims'], f'Affe federt nicht auf den Sims: {r}'
        assert 'schirmauf' in r['log'] and 'trampolin' in r['log'], f'Ton fehlt: {r["log"]}'
        assert r['zu'] and r['ohne'] == 0, f'nach dem Loslassen noch Trampolin: {r}'
    finally:
        srv.shutdown()

@test
async def koop_pusten_schraeg(g):
    """Nutzerwunsch: Pusten auch schräg nach oben – W + D = oben-rechts, W + A = oben-links. Der Strahl trägt das Schweinchen
    mit Schirm nach oben und zur Seite; der Affe steht still und schaut zur Blasrichtung."""
    srv = await koop_testlevel(g)
    try:
        r = await g.ev("""(() => { """ + KOOP_SCHRITTE + """ const e = {};
          try {
            for(const [taste, sx] of [['right', 1], ['left', -1]]){
              for(const k in KEYS) KEYS[k] = false; p1.puste = 1; p1.pusteLeer = false;
              stell(p1, 1060, 720); stell(p2, 300, 720); for(let i = 0; i < 6; i++) st();
              KEYS[p1.keys.pusten] = true; KEYS[p1.keys.pull] = true; KEYS[p1.keys[taste]] = true;
              for(let i = 0; i < 8; i++) st();
              const S = pusteStrahlJetzt;
              e[taste] = {richtung: p1.pusteRichtung, still: Math.abs(p1.x - 1060) < 1, schaut: p1.facing === sx};
              // Schweinchen mit offenem Schirm 2 Kästchen schräg über dem Mund in den Strahl setzen
              p2.x = S.ox + S.ux*90; p2.y = S.oy + S.uy*90 + 20; p2.vx = 0; p2.vy = 0; p2.grounded = false; p2._px = p2.x; p2._py = p2.y;
              const x0 = p2.x, y0 = p2.y; KEYS[p2.keys.glide] = true;
              for(let i = 0; i < 20; i++) st();
              e[taste].dx = Math.round((p2.x - x0)*sx); e[taste].dy = Math.round(y0 - p2.y);
            }
          } finally { for(const k in KEYS) KEYS[k] = false; menuScreen = null; }
          return e; })()""")
        for taste, dirn in (('right', 'hr'), ('left', 'hl')):
            e = r[taste]
            assert e['richtung'] == dirn and e['still'] and e['schaut'], (taste, e)
            assert e['dx'] > 20 and e['dy'] > 10, f'schräger Strahl trägt nicht nach oben und zur Seite: {taste} {e}'
    finally:
        srv.shutdown()

@test
async def koop_pusten(g):
    """Dschungel-Neu: Affe hält die Spezial-Taste (H) -> pustet und steht still; W = nach oben, A/D = zur Seite (dreht sich nur).
    Der Strahl trägt das Schweinchen mit offenem Schirm hinauf (wie ein Aufwind) bis auf den 9 Reihen hohen Sims, zur Seite
    schiebt er es. Der Puste-Balken leert sich in PUSTE_DAUER Schritten, ganz leer geht es erst ab PUSTE_NEUSTART weiter, ohne
    Pusten lädt er wieder voll. Ohne Schirm trägt der Wind nicht nach oben. Der Affe selbst fliegt nicht."""
    srv = await koop_testlevel(g)
    try:
        r = await g.ev("""(() => { """ + KOOP_SCHRITTE + """ const e = {};
          try {
            // hoch: Schweinchen über dem Affen mit Schirm -> auf den hohen Sims (1080–1280, y 360, 9 Reihen)
            stell(p1, 1060, 720); stell(p2, 1060, 720); for(let i = 0; i < 6; i++) st();
            KEYS[p1.keys.pusten] = true; KEYS[p1.keys.pull] = true;   // (W + D wäre schräg, Test koop_pusten_schraeg)
            for(let i = 0; i < 4; i++) st(); e.affeStill = Math.abs(p1.x - 1060) < 1; e.richtung = p1.pusteRichtung;
            KEYS[p2.keys.jump] = true; KEYS[p2.keys.jump + '_pressed'] = true; st(); KEYS[p2.keys.glide] = true;
            let top = 1e9; for(let i = 0; i < 110; i++){ if(i === 20) KEYS[p2.keys.jump] = false; KEYS[p2.keys.right] = p2.y < 350 && p2.x < 1160; st(); top = Math.min(top, p2.y); }
            KEYS[p2.keys.right] = false; KEYS[p2.keys.glide] = false; for(let i = 0; i < 40; i++) st();
            e.schweinHoch = (720 - top)/40; e.aufSims = p2.grounded && Math.abs(p2.y - 360) < 1; e.affeY = p1.y; e.log = SFX_LOG.slice(-60);
            // Balken: leer pusten, dann laden
            for(const k in KEYS) KEYS[k] = false; for(let i = 0; i < 400; i++) st(); e.voll = p1.puste;
            KEYS[p1.keys.pusten] = true; let n = 0; while(p1.pusteAn || n === 0){ st(); n++; if(n > 400) break; } e.dauer = n; e.leer = p1.pusteLeer;
            // Taste weiter gehalten (Nutzer-Rückmeldung „lädt nicht, flackert“): bleibt aus und lädt trotzdem
            let an = 0; for(let i = 0; i < 300; i++){ st(); if(p1.pusteAn) an++; } e.nochAus = !an; e.geladenGehalten = p1.puste;
            KEYS[p1.keys.pusten] = false; for(let i = 0; i < 400; i++) st(); e.wieder = p1.puste;
            // ohne Schirm: trägt nicht nach oben
            stell(p1, 1060, 720); stell(p2, 1060, 640); KEYS[p1.keys.pusten] = true; KEYS[p1.keys.pull] = true;
            for(let i = 0; i < 60; i++) st(); e.ohneSchirm = p2.grounded && p2.y === 720;
            // zur Seite: Schweinchen mit Schirm wird nach rechts geschoben
            for(const k in KEYS) KEYS[k] = false; p1.puste = 1; p1.pusteLeer = false; stell(p1, 300, 720); for(let i = 0; i < 4; i++) st(); stell(p2, 420, 700);
            KEYS[p1.keys.pusten] = true; KEYS[p1.keys.right] = true; KEYS[p2.keys.glide] = true; for(let i = 0; i < 30; i++) st();
            e.seite = p2.x - 400; e.affeStill2 = Math.abs(p1.x - 300) < 1;
          } finally { for(const k in KEYS) KEYS[k] = false; menuScreen = null; }
          return e; })()""")
        assert r['affeStill'] and r['richtung'] == 'hoch', f'Affe soll still stehen und nach oben pusten: {r}'
        assert r['schweinHoch'] > 8.5 and r['aufSims'], f'Wind trägt das Schweinchen nicht auf den Sims: {r}'
        assert abs(r['affeY'] - 720) < 1, f'der Affe selbst darf nicht fliegen: {r}'
        assert 'pustenstart' in r['log'] and 'pusten' in r['log'], f'Ton fehlt: {r["log"]}'
        assert r['voll'] == 1 and abs(r['dauer'] - 160) <= 3 and r['leer'] and r['nochAus'] and r['geladenGehalten'] > 0.9, f'Puste-Balken falsch: {r}'
        assert r['wieder'] == 1, f'Balken lädt nicht wieder: {r}'
        assert r['ohneSchirm'], f'ohne Schirm darf der Wind nicht tragen: {r}'
        assert r['seite'] > 60 and r['affeStill2'], f'Seiten-Wind schiebt nicht: {r}'
    finally:
        srv.shutdown()

@test
async def windrad_anpusten(g):
    """Dschungel-Neu (elemente/windrad.js): nur der Puste-Wind dreht ein Windrad. „umschalten“: dreht es sich voll, schaltet
    es seine Nummer einmal um (Tür auf) und bleibt so, auch wenn es ausläuft; nochmal anpusten = wieder zu. „solange“: die
    Nummer ist an, solange es sich dreht, läuft es aus, geht sie wieder aus. In die andere Richtung gepustet dreht sich nichts."""
    srv = await koop_testlevel(g)
    try:
        r = await g.ev("""(() => { """ + KOOP_SCHRITTE + """ const e = {};
          const pusten = (n, r) => { r = r || p1.keys.right; KEYS[p1.keys.pusten] = true; KEYS[r] = true; for(let i = 0; i < n; i++) st(); KEYS[p1.keys.pusten] = false; KEYS[r] = false; };
          const tuer = l => solids.filter(s => s.type === 'door' && s.link === l).every(s => s.open);
          try {
            stell(p2, 1900, 720); stell(p1, 1960, 720); for(let i = 0; i < 6; i++) st();
            pusten(60, p1.keys.left); e.weit = windraeder[0].dreh;   // vom Windrad weg gepustet
            stell(p1, 1960, 720); for(let i = 0; i < 6; i++) st(); p1.puste = 1; p1.pusteLeer = false;
            pusten(40); e.an1 = !!linkOn[1] && tuer(1);
            for(let i = 0; i < 300; i++) st(); e.bleibt = !!linkOn[1] && windraeder[0].dreh < 0.1;
            p1.puste = 1; p1.pusteLeer = false; pusten(40); e.wiederAus = !linkOn[1]; for(let i = 0; i < 200; i++) st();
            stell(p1, 2560, 720); for(let i = 0; i < 6; i++) st(); p1.puste = 1; p1.pusteLeer = false;
            pusten(40); e.an2 = !!linkOn[2] && tuer(2);
            for(let i = 0; i < 300; i++) st(); e.aus2 = !linkOn[2];
            e.log = SFX_LOG.slice(-80);
          } finally { for(const k in KEYS) KEYS[k] = false; menuScreen = null; }
          return e; })()""")
        assert r['weit'] == 0, f'vom Windrad weg gepustet: es darf sich nicht drehen: {r}'
        assert r['an1'] and r['bleibt'] and r['wiederAus'], f'Windrad „umschalten“ falsch: {r}'
        assert r['an2'] and r['aus2'], f'Windrad „solange es dreht“ falsch: {r}'
        assert 'windrad' in r['log'], f'Ton fehlt: {r["log"]}'
    finally:
        srv.shutdown()

@test
async def blattfloss_wind(g):
    """Dschungel-Neu (elemente/blattfloss.js): das Blatt-Floß über der Grube bewegt sich ohne Wind nicht (auch nicht,
    wenn jemand darauf läuft); der Seiten-Wind des Affen schiebt es samt Schweinchen bis ans Ende der Schiene, dort bleibt es
    liegen; nach dem Neustart liegt es wieder am Anfang. Nach oben gepustet bewegt es sich nicht."""
    srv = await koop_testlevel(g)
    try:
        r = await g.ev("""(() => { """ + KOOP_SCHRITTE + """ const e = {}, B = blattFloesse[0];
          try {
            stell(p2, 1460, 720); stell(p1, 1330, 720); for(let i = 0; i < 30; i++) st();
            e.traegt = p2.grounded && Math.abs(p2.y - 720) < 1; e.ruhig = B.x === 1400;
            KEYS[p1.keys.pusten] = true; KEYS[p1.keys.pull] = true; for(let i = 0; i < 30; i++) st(); e.hochNichts = B.x === 1400;
            KEYS[p1.keys.pull] = false; KEYS[p1.keys.right] = true; for(let i = 0; i < 125; i++) st();   // (Balken reicht 160 Schritte; danach liefe er los)
            KEYS[p1.keys.pusten] = false; KEYS[p1.keys.right] = false; for(let i = 0; i < 60; i++) st();
            e.ende = B.x; e.schwein = p2.x; e.lebt = !deathState;
            resetLevel(); for(let i = 0; i < 3; i++) st(); e.neu = B.x;
          } finally { for(const k in KEYS) KEYS[k] = false; menuScreen = null; }
          return e; })()""")
        assert r['traegt'] and r['ruhig'] and r['hochNichts'], f'Blatt-Floß trägt nicht / bewegt sich ohne Seiten-Wind: {r}'
        assert r['ende'] == 1640 and r['schwein'] > 1640 and r['lebt'], f'Wind schiebt das Floß nicht samt Schweinchen ans Ende: {r}'
        assert r['neu'] == 1400, f'nach dem Neustart nicht am Anfang: {r}'
    finally:
        srv.shutdown()

@test
async def tasten_belegen_menue(g):
    """Nacht-Ausbau: Optionen → Tasten belegen. Standard = alte Belegung (+ Dash K / Num 3). Taste ändern, Esc bricht ab,
    gesperrte Tasten gehen nicht, Konflikt wird markiert und blockiert das Verlassen, Zurücksetzen je Spieler,
    Speichern unter monchichi.tasten, nach Neuladen aktiv (auch für die Figur im Spiel)."""
    srv = webserver(); p = g.p
    try:
        await p.goto(srv.url + 'index.html'); await p.evaluate("localStorage.clear()")
        await tasten_menue_oeffnen(g, srv)
        ks = await g.ev("JSON.parse(JSON.stringify(KEYSETS))")
        for n in (1, 2):
            for a, k in TASTEN_ALT[n].items(): assert ks[str(n)][a] == k, (n, a, ks[str(n)][a])
        assert ks['1']['dash'] == 'KeyK' and ks['2']['dash'] == 'Numpad3', ks
        # Springen von Spieler 1 auf L
        await tb_knopf(g, 1, 'jump'); assert await g.ev("!!document.querySelector('#sm-tb-grid .tb-k.fang')")
        await p.keyboard.press('KeyL'); await p.wait_for_timeout(350)
        assert await g.ev("KEYSETS[1].jump") == 'KeyL'
        # Esc bricht ab (Belegung bleibt)
        await tb_knopf(g, 1, 'use'); await p.keyboard.press('Escape'); await p.wait_for_timeout(350)
        assert await g.ev("KEYSETS[1].use") == 'KeyJ' and await g.ev("document.querySelector('#sm-s-tasten.active') !== null")
        # gesperrte Taste (R = Neustart) wird abgelehnt, Fangmodus bleibt -> dann Esc
        await tb_knopf(g, 1, 'use'); await p.keyboard.press('KeyR'); await p.wait_for_timeout(300)
        assert await g.ev("KEYSETS[1].use") == 'KeyJ'
        await p.keyboard.press('Escape'); await p.wait_for_timeout(350)
        # Konflikt: Spieler 2 Fähigkeit auf L -> beide rot, Verlassen blockiert (Dialog)
        await tb_knopf(g, 2, 'ability'); await p.keyboard.press('KeyL'); await p.wait_for_timeout(350)
        assert await g.ev("document.querySelectorAll('#sm-tb-grid .tb-k.konflikt').length") == 2
        await p.click('#sm-tb-back'); await p.wait_for_timeout(400)
        assert await g.ev("document.querySelector('#sm-modal').classList.contains('on')"), 'kein Konflikt-Dialog'
        await p.click('#sm-modal-btns .btn >> nth=0'); await p.wait_for_timeout(400)   # weiter ändern
        assert await g.ev("document.querySelector('#sm-s-tasten.active') !== null")
        # Spieler 2 zurücksetzen -> Konflikt weg, Verlassen speichert
        await p.click('#sm-tb-grid .tb-std >> nth=1'); await p.wait_for_timeout(350)
        assert await g.ev("KEYSETS[2].ability") == 'Numpad1' and await g.ev("document.querySelectorAll('#sm-tb-grid .tb-k.konflikt').length") == 0
        await p.click('#sm-tb-back'); await p.wait_for_timeout(500)
        assert await g.ev("document.querySelector('#sm-s-options.active') !== null")
        gesp = await g.ev("JSON.parse(localStorage.getItem('monchichi.tasten'))")
        assert gesp['tastatur']['1']['jump'] == 'KeyL' and gesp['tastatur']['2']['ability'] == 'Numpad1', gesp
        # Anzeige in den Optionen zeigt die neue Taste
        assert 'L' in await g.ev("[...document.querySelectorAll('#sm-ctrl-cards .key')].map(e => e.textContent)")
        # neu laden: Belegung bleibt, Spiel-Figur (Spieler 1 = Affe) springt mit L
        await p.goto(srv.url + 'index.html?testlevel=bahnen')
        await p.wait_for_function("typeof p1 !== 'undefined' && p1 && solids.length > 3 && menuScreen === null", timeout=15000)
        assert await g.ev("KEYSETS[1].jump") == 'KeyL' and await g.ev("p1.keys.jump") == 'KeyL'
        assert 'L' in await g.ev("document.getElementById('hudMKeys').textContent")
        await g.ev("p1.x = 300; p1.y = 720; p1.vy = 0"); await g.steps(10)
        await p.keyboard.down('KeyL'); await g.steps(6); await p.keyboard.up('KeyL')
        assert await g.ev("p1.vy < 0 || !p1.grounded"), 'Affe springt nicht mit der neuen Taste'
        # Zurücksetzen Spieler 1 stellt die alte Belegung wieder her
        await g.ev("KEYSETS[1].jump = TASTEN_STANDARD[1].jump; tastenSpeichern(); tastenAnwenden()")
        assert await g.ev("p1.keys.jump") == 'Space'
    finally:
        srv.shutdown()

PAD_STUB_TYP = """window.__pad = {id: '%s', index: 0, connected: true, axes:[0,0,0,0], buttons: Array.from({length:17},()=>({pressed:false,value:0})), mapping:'standard'};
navigator.getGamepads = () => [window.__pad, null, null, null];"""

@test
async def tasten_controller_je_typ(g):
    """Nacht-Ausbau: Controller-Belegung frei (auch Schultertasten/Trigger), je Spieler UND Controller-Typ gespeichert;
    andere Typen behalten die Standard-Belegung; Options/Share sind gesperrt. Simulierter Controller (kein echtes Gerät)."""
    srv = webserver(); kx = await g.p.context.browser.new_context(viewport={'width': 1280, 'height': 720}); p = await kx.new_page(); g2 = Game(p)
    try:
        await p.add_init_script(PAD_STUB_TYP % 'Xbox Wireless Controller (STANDARD GAMEPAD Vendor: 045e)')
        await p.goto(srv.url + 'index.html'); await p.evaluate("localStorage.clear()")
        await tasten_menue_oeffnen(g2, srv)
        assert await g2.ev("padTypAktuell[0]") == 'xbox'
        await p.click('#sm-tb-seg button[data-art="pad"]'); await p.wait_for_timeout(300)
        assert 'Xbox' in await g2.ev("document.getElementById('sm-tb-typ').textContent")
        # Dash von Spieler 1 auf LB (Knopf 4; RB = 5 ist Standard für die Spezial-Taste, Dschungel-Neu)
        async def druck(knopf, bis, wert="{pressed: true, value: 1}"):
            # gedrückt halten, bis das Menü reagiert hat (langsame Rechner: nicht feste Zeiten), dann loslassen
            await g2.ev(f"__pad.buttons[{knopf}] = {wert}")
            await p.wait_for_function(bis, timeout=8000)
            await g2.ev(f"__pad.buttons[{knopf}] = {{pressed: false, value: 0}}"); await p.wait_for_timeout(300)
        await tb_knopf(g2, 1, 'dash')
        await druck(4, "PADSETS[1].xbox.dash === 4")
        assert await g2.ev("PADSETS[1].xbox.dash") == 4
        assert await g2.ev("PADSETS[1].playstation.dash") == 3 and await g2.ev("PADSETS[2].xbox.dash") == 3
        # Trigger (analog, nur value) auf Fähigkeit
        await tb_knopf(g2, 1, 'ability')
        await druck(7, "PADSETS[1].xbox.ability === 7", "{pressed: false, value: 0.9}")
        assert await g2.ev("PADSETS[1].xbox.ability") == 7
        # Share (8) gesperrt, Options (9) bricht ab
        await tb_knopf(g2, 1, 'use')
        await druck(8, "document.getElementById('sm-toast').textContent.includes('gesperrt')")
        assert await g2.ev("PADSETS[1].xbox.use") == 1 and await g2.ev("!!document.querySelector('.tb-k.fang')")
        await druck(9, "!document.querySelector('.tb-k.fang')")
        assert await g2.ev("!document.querySelector('.tb-k.fang')") and await g2.ev("PADSETS[1].xbox.use") == 1
        await p.click('#sm-tb-back'); await p.wait_for_timeout(500)
        gesp = await g2.ev("JSON.parse(localStorage.getItem('monchichi.tasten'))")
        assert gesp['pad']['1']['xbox']['dash'] == 4 and gesp['pad']['1']['playstation']['dash'] == 3, gesp['pad']['1']
        # im Spiel: LB dasht mit dem Xbox-Controller, Y (3) nicht mehr
        await p.goto(srv.url + 'index.html?testlevel=bahnen')
        await p.wait_for_function("typeof p1 !== 'undefined' && p1 && solids.length > 3 && menuScreen === null", timeout=15000)
        await g2.ev("__pad.buttons[3] = {pressed: true, value: 1}; pollGamepads()")
        assert not await g2.ev("!!PAD[KEYSETS[1].dash]")
        await g2.ev("__pad.buttons[3] = {pressed: false, value: 0}; __pad.buttons[4] = {pressed: true, value: 1}; pollGamepads()")
        assert await g2.ev("!!PAD[KEYSETS[1].dash]")
        # derselbe Platz mit PlayStation-Controller: Standard (△ = 3) gilt
        await g2.ev("__pad.buttons[4] = {pressed: false, value: 0}; __pad.id = 'Wireless Controller (STANDARD GAMEPAD Vendor: 054c Product: 09cc)'; __pad.buttons[3] = {pressed: true, value: 1}; pollGamepads()")
        assert await g2.ev("padTypAktuell[0]") == 'playstation' and await g2.ev("!!PAD[KEYSETS[1].dash]")
        await g2.ev("__pad.buttons[3] = {pressed: false, value: 0}; pollGamepads()")
    finally:
        await kx.close(); srv.shutdown()

@test
async def tasten_alter_spielstand(g):
    """Nacht-Ausbau: Spielstand ohne Tasten-Eintrag (vor dem Ausbau) oder kaputter Eintrag -> Standard-Belegung;
    teilweise gespeicherte Belegung ergänzt fehlende Aktionen (z. B. Dash) mit dem Standard. Spielstand bleibt erhalten."""
