@test
async def bausteine_nacht(g):
    """Nacht-Ausbau: Bausteine B1–B7 (levels/test/bausteine-nacht.json, tests/bausteine/testlevel_bauen.py) – jeder mit
    beiden Figuren (B7 nur Schweinchen) per Bot geschafft, und jede Gegenprobe ohne die neue Mechanik scheitert:
    B1 Dash-Grube · B2 Durchbruch-Tor + Grube (Bruch-Fenster) · B3 Haftfläche über Grube · B4 Kamin mit Durchbruch oben in der Seitenwand
    · B5 Haken -> Durchbruch (Schweinchen: Segeln + Dash) · B6 Haftfläche + Dash · B7 Segeln + Dash (Rolle Schweinchen)."""
    await koop_level(g, 'test/bausteine-nacht.json')
    await g.ev("levelWelt = 'vulkan'")   # Testlevel im Dschungel-Look, dort ist der Dash aus (DASH_AUS_WELTEN) – hier geht es um den Dash
    faelle = [
        ('B1', 'm', 17, NB.nb_dashgrube(19), 30, [k_lauf(19, -8), {'press': ['jump'], 'hold': ['right', 'jump'], 'frames': 12}, NB.LANDEN]),
        ('B1', 'f', 17, k_segeln(19), 30, None),
        ('B2', 'm', 33, NB.nb_bruchtor(38), 48, [{'hold': ['right'], 'frames': 200}]),
        ('B2', 'f', 33, NB.nb_bruchtor(38), 48, None),
        ('B3', 'm', 58, NB.nb_haft(64, 79), 79, [k_lauf(64), {'press': ['jump'], 'hold': ['jump', 'right'], 'frames': 40}, NB.LANDEN]),
        ('B3', 'f', 58, NB.nb_haft(64, 79), 79, None),
        ('B4', 'm', 90, NB.nb_bruchkamin(98, 6, 104), 104, [k_lauf(98), {'climb': True, 'dir': 1, 'until': f'P.x >= {kx(104)} && P.grounded', 'frames': 600}]),
        ('B4', 'f', 90, NB.nb_bruchkamin(98, 6, 104), 104, None),
        ('B5', 'm', 119, NB.nb_haken_bruch(124, 138), 139, NB.nb_haken_bruch(124, 138)[:3] + [NB.LANDEN]),
        ('B5', 'f', 119, NB.nb_segel_dash(125, 134), 139, k_segeln(125)),
        ('B6', 'm', 143, NB.nb_haft_dash(150, 160), 166, NB.nb_haft(150, 160)),
        ('B6', 'f', 143, NB.nb_haft_dash(150, 160), 166, None),
        ('B7', 'f', 180, NB.nb_segel_dash(185, 195), 203, k_segeln(185)),
    ]
    fehler = []
    for name, wer, c, plan, ziel, gegen in faelle:
        anders = 'f' if wer == 'm' else 'm'
        r = await koop(g, **{wer: kat(c, 14), anders: kat(c - 2, 14)}, plans={wer: plan}, maxFrames=3000)
        if not (r.get('done') and r['pos'][wer][0] >= ziel): fehler.append(f"{name} {wer}: {r.get('pos')} {r.get('dead')}")
        if gegen:
            r = await koop(g, **{wer: kat(c, 14), anders: kat(c - 2, 14)}, plans={wer: gegen}, maxFrames=1500)
            if r.get('done') and r['pos'][wer][0] >= ziel and r['pos'][wer][1] >= (4 if name == 'B4' else 14):
                fehler.append(f"{name} {wer}: Gegenprobe ohne neue Mechanik geht auch: {r.get('pos')}")
    assert not fehler, fehler

import stellen as NS   # neue Stellen in den Leveln (tests/bausteine/stellen.py)

async def nacht_stellen_pruefen(g, welt):
    """alle neuen Stellen einer Welt mit dem Bot spielen (+ Gegenprobe ohne neue Mechanik)"""
    fehler, geladen = [], None
    for st in NS.je_welt(welt):
        if os.environ.get('STELLEN_FILTER') and os.environ['STELLEN_FILTER'] not in st['name']: continue   # nur zum Nachprüfen einzelner Stellen
        if st['level'] != geladen:
            await koop_level(g, st['level']); geladen = st['level']
        wer = st['wer']; anders = 'f' if wer == 'm' else 'm'
        plan = st['plan']; plaene = None
        if st.get('baustein') in ('B2', 'S4') and await g.ev("DASH_AUS_WELTEN.includes(levelWelt)"):   # ohne Dash: der Affe pustet die Wand um
            if st['baustein'] == 'S4' and wer == 'f':   # Schweinchen-Münze in der Nische: Affe pustet auf, dann holt das Schweinchen sie
                plaene = {'m': NB.mit_pusten(st['plan']), 'f': [{'wait': "!solids.some(s => s.type === 'bruch' && !s.gone && Math.abs(s.x + s.w/2 - Q.x) < 140)", 'frames': 600},
                                                               {'frames': 90}] + NB.mit_pusten(st['plan'])}
            else:
                wer, anders, plan = 'm', 'f', NB.mit_pusten(st['plan'])
        def ok(r):
            if not r.get('done'): return False
            c, rr = r['pos'][wer]
            return c >= st['ziel'] and (st.get('ziel_reihe') is None or abs(rr - st['ziel_reihe']) < 0.6)
        if plaene:   # Affe ein Kästchen weiter vorn, das Schweinchen wartet auf seinem Platz dahinter
            vorn = (st['start'][0] + 1 if st['partner'][0] < st['start'][0] else st['start'][0] - 1, st['start'][1])
            r = await koop(g, m=kat(*vorn), f=kat(*st['start']), plans=plaene,
                links=st['links'], maxFrames=st.get('frames', 3000) + 900)
        else: r = await koop(g, **{wer: kat(*st['start']), anders: kat(*st['partner'])}, plans={wer: plan}, links=st['links'], maxFrames=st.get('frames', 3000))
        if not (r.get('done') and not r.get('dead') if plaene else ok(r)): fehler.append(f"{st['level']} {st['name']} ({wer}): {r.get('pos')} tot={r.get('dead')} schritte={r.get('steps')}")
        elif st.get('muenze') and not await g.ev(f"coins.some(c => Math.abs(c.x - {kx(st['muenze'][0])}) < 2 && Math.abs(c.y - {st['muenze'][1] * 40 + 20}) < 2 && c.taken)"):
            fehler.append(f"{st['level']} {st['name']} ({wer}): Münze {st['muenze']} nicht eingesammelt")
        if st['gegen']:
            r = await koop(g, **{wer: kat(*st['start']), anders: kat(*st['partner'])}, plans={wer: st['gegen']}, links=st['links'], maxFrames=st.get('frames', 3000))
            if st.get('gegen_muenze'):   # Versteck: drüberlaufen darf die Münze nicht holen
                if await g.ev(f"coins.some(c => Math.abs(c.x - {kx(st['muenze'][0])}) < 2 && Math.abs(c.y - {st['muenze'][1] * 40 + 20}) < 2 && c.taken)"):
                    fehler.append(f"{st['level']} {st['name']} ({wer}): Gegenprobe holt die Münze ohne Dash")
            elif ok(r): fehler.append(f"{st['level']} {st['name']} ({wer}): Gegenprobe ohne neue Mechanik kommt auch durch {r.get('pos')}")
    return fehler

